CREATE TABLE `clima` (
  `id` int NOT NULL DEFAULT '1',
  `banner_titulo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `banner_titulo_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `banner_subtitulo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `banner_subtitulo_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `intro_texto` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `intro_texto_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `intro_imagen` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `aside_texto` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `aside_texto_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `aside_btn` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Consultar Ahora',
  `aside_btn_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Consult Now',
  `aside_imagen` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `cta_titulo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `cta_titulo_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `cta_texto` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `cta_texto_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `cta_btn` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `cta_btn_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `cta_imagen` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `aside_test_tit` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `aside_test_tit_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `aside_test_txt` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `aside_test_txt_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `aside_test_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `aside_test_fecha` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `aside_test_fecha_en` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `color_titulo` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `tamano_titulo` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `color_texto` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `tamano_texto` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `clima` (`id`, `banner_titulo`, `banner_titulo_en`, `banner_subtitulo`, `banner_subtitulo_en`, `intro_texto`, `intro_texto_en`, `intro_imagen`, `aside_texto`, `aside_texto_en`, `aside_btn`, `aside_btn_en`, `aside_imagen`, `cta_titulo`, `cta_titulo_en`, `cta_texto`, `cta_texto_en`, `cta_btn`, `cta_btn_en`, `cta_imagen`, `aside_test_tit`, `aside_test_tit_en`, `aside_test_txt`, `aside_test_txt_en`, `aside_test_img`, `aside_test_fecha`, `aside_test_fecha_en`, `color_titulo`, `tamano_titulo`, `color_texto`, `tamano_texto`) VALUES ('1', 'El Clima en Cusco', 'Weather in Cusco', 'Conoce las mejores temporadas para visitar la ciudad imperial', 'Discover the best seasons to visit the imperial city', '# Clima en Cusco\r\n\r\nCusco cuenta con un clima andino caracterizado por días templados, noches frescas y una gran variación de temperatura entre el día y la noche. Gracias a su ubicación en la Cordillera de los Andes, la región presenta dos estaciones principales que influyen en las actividades turísticas y de aventura a lo largo del año.\r\n\r\n# ☀️ Temporada Seca (Abril - Octubre)\r\n\r\nLa temporada seca es considerada la mejor época para visitar Cusco y realizar actividades al aire libre como trekking, excursiones y visitas a sitios arqueológicos. Durante estos meses predominan los días soleados, cielos despejados y escasas precipitaciones.\r\n\r\n✅Meses: Abril, Mayo, Junio, Julio, Agosto, Septiembre y Octubre.\r\n✅ Temperatura promedio: Entre 15°C y 22°C durante el día.\r\n✅ Noches frías que pueden descender hasta los 0°C o menos en zonas de alta montaña.\r\n✅ Ideal para visitar Machu Picchu, la Montaña de 7 Colores, Laguna Humantay, Ausangate y el Valle Sagrado.\r\n\r\n# 🌧️ Temporada de Lluvias (Noviembre - Marzo)\r\n\r\nDurante estos meses las lluvias son más frecuentes, especialmente entre enero y febrero. Sin embargo, la vegetación se muestra más verde y los paisajes adquieren una belleza única que atrae a muchos viajeros.\r\n\r\n✅ Meses: Noviembre, Diciembre, Enero, Febrero y Marzo.\r\n✅ Temperatura promedio: Entre 12°C y 20°C.\r\n✅ Lluvias ocasionales o intensas dependiendo del mes.\r\n✅ Paisajes más verdes y menor afluencia de turistas en algunos destinos.\r\n\r\n# 🌤️ Temperatura Durante el Año\r\n\r\nIndependientemente de la temporada, es común experimentar diferentes condiciones climáticas en un mismo día. Las mañanas suelen ser frescas, el mediodía puede ser soleado y cálido, mientras que las noches son generalmente frías.\r\n\r\n# 🎒 Recomendaciones\r\n\r\n✅ Llevar ropa en capas para adaptarse a los cambios de temperatura.\r\n✅ Utilizar protector solar durante todo el año.\r\n✅ Contar con una casaca abrigadora para las noches.\r\n✅ Llevar impermeable o poncho de lluvia durante la temporada húmeda.\r\n✅ Consultar el clima específico de cada destino, ya que la altitud puede influir considerablemente en las condiciones meteorológicas.\r\n\r\n- En IntiPath Tours te ayudamos a planificar tu viaje según la temporada, para que disfrutes de la mejor experiencia posible en cada rincón de Cusco.', '# Cusco Climate\r\n\r\nCusco has an Andean climate characterized by mild days, cool nights, and a significant temperature variation between day and night. Thanks to its location in the Andes Mountains, the region experiences two main seasons that influence tourism and adventure activities throughout the year.\r\n\r\n# ☀️ Dry Season (April - October)\r\n\r\nThe dry season is considered the best time to visit Cusco and enjoy outdoor activities such as trekking, excursions, and visits to archaeological sites. During these months, sunny days, clear skies, and little rainfall predominate.\r\n\r\n✅ Months: April, May, June, July, August, September, and October.\r\n\r\n✅ Average temperature: Between 15°C and 22°C during the day.\r\n\r\n✅ Cold nights that can drop to 0°C or below in high-altitude areas. ✅ Ideal for visiting Machu Picchu, Rainbow Mountain, Humantay Lagoon, Ausangate, and the Sacred Valley.\r\n\r\n# 🌧️ Rainy Season (November - March)\r\n\r\nDuring these months, rainfall is more frequent, especially between January and February. However, the vegetation is lush and green, and the landscapes take on a unique beauty that attracts many travelers.\r\n\r\n✅ Months: November, December, January, February, and March.\r\n\r\n✅ Average Temperature: Between 12°C and 20°C.\r\n\r\n✅ Occasional or heavy rain depending on the month.\r\n\r\n✅ Greener landscapes and fewer tourists in some destinations.\r\n\r\n# 🌤️ Temperature Throughout the Year\r\n\r\nRegardless of the season, it is common to experience different weather conditions in a single day. Mornings are usually cool, midday can be sunny and warm, while nights are generally cold.\r\n\r\n# 🎒 Recommendations\r\n\r\n✅ Pack layers to adapt to temperature changes.\r\n\r\n✅ Use sunscreen year-round.\r\n\r\n✅ Bring a warm jacket for the evenings.\r\n\r\n✅ Pack a raincoat or poncho during the rainy season.\r\n\r\n✅ Check the specific weather forecast for each destination, as altitude can significantly influence weather conditions.\r\n\r\n- At IntiPath Tours, we help you plan your trip according to the season, so you can enjoy the best possible experience in every corner of Cusco.', 'clima_banner_1781729075.jpg', 'La mejor temporada para visitar Cusco dependerá del tipo de experiencia que estés buscando.\r\n\r\nEn IntiPath Tours te ayudaremos a elegir la mejor fecha según tus intereses, actividades preferidas y condiciones de viaje para que aproveches al máximo tu aventura en Cusco.', 'The best time to visit Cusco depends on the type of experience you\'re looking for.\r\n\r\nAt IntiPath Tours, we\'ll help you choose the best dates based on your interests, preferred activities, and travel conditions so you can make the most of your adventure in Cusco.', 'Contáctanos', 'Contact Us', 'clima_spec_1781706390.jpg', '¿Listo para descubrir Cusco?', 'Ready to discover Cusco?', 'Reserve ahora y viva una experiencia única en la ciudad imperial', 'Book now and experience a unique adventure in the imperial city', 'Reservar Ahora', 'Book Now', '', '', '', NULL, NULL, '', '', '', '#0f9b9e', '3rem', '#444444', '1.1rem');

DROP TABLE IF EXISTS `colores`;
CREATE TABLE `colores` (
  `id` int NOT NULL AUTO_INCREMENT,
  `variable` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `nombre` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `valor_defecto` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `valor_actual` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `grupo` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `descripcion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `orden` int DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `variable` (`variable`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

