INSERT INTO `como_reservar` (`id`, `banner_titulo`, `banner_titulo_en`, `banner_subtitulo`, `banner_subtitulo_en`, `intro_texto`, `intro_texto_en`, `intro_imagen`, `aside_texto`, `aside_texto_en`, `aside_btn`, `aside_btn_en`, `aside_imagen`, `cta_titulo`, `cta_titulo_en`, `cta_texto`, `cta_texto_en`, `cta_btn`, `cta_btn_en`, `cta_imagen`, `aside_test_tit`, `aside_test_tit_en`, `aside_test_txt`, `aside_test_txt_en`, `aside_test_img`, `aside_test_fecha`, `aside_test_fecha_en`, `color_titulo`, `tamano_titulo`, `color_texto`, `tamano_texto`) VALUES ('1', 'Cómo Reservar', 'How to Book', 'El proceso de reserva simple y seguro', 'Simple and secure booking process', 'Reservar tu próxima aventura con IntiPath Tours es un proceso rápido, seguro y sencillo. Nuestro equipo te acompañará en cada etapa para garantizar una experiencia organizada y sin preocupaciones.\r\n\r\n# 1. Elige tu Tour\r\n✅Explora nuestra variedad de experiencias y selecciona el tour que mejor se adapte a tus intereses, tiempo disponible y nivel de aventura.\r\n\r\n# 2. Solicita Información\r\n✅Contáctanos a través de WhatsApp, correo electrónico o redes sociales. Uno de nuestros asesores te brindará información detallada sobre itinerarios, tarifas, disponibilidad, inclusiones y nivel de dificultad del tour.\r\n\r\n# 3. Recibe tu Itinerario\r\n\r\n✅Te enviaremos el programa completo del tour, incluyendo horarios, lugares a visitar, servicios incluidos, recomendaciones y toda la información necesaria para planificar tu viaje.\r\n\r\n# 4. Completa tus Datos de Reserva\r\n\r\n✅Nuestro personal se comunicará contigo para solicitar la información necesaria para la reserva, como nombres completos, número de documento o pasaporte, nacionalidad, fecha de nacimiento y demás datos requeridos según el servicio contratado.\r\n\r\n# 5. Infórmanos sobre tu Estado de Salud\r\n\r\n✅Para garantizar una experiencia segura, es importante que nos informes con anticipación sobre cualquier condición médica, limitación física, alergia, lesión o requerimiento especial que debamos considerar durante el desarrollo del tour.\r\n\r\n# 6. Recomendaciones de Equipaje\r\n\r\n✅Antes de tu viaje, te brindaremos una lista de artículos recomendados según el destino y la temporada. Generalmente sugerimos llevar documentación personal, ropa cómoda, casaca abrigadora, impermeable, zapatillas de trekking, gorro para el sol, lentes de sol, artículos de aseo personal, medicamentos de uso habitual y dinero en efectivo para gastos adicionales.\r\n\r\n# 7. Confirmación y Pago\r\n\r\n✅Una vez verificada la disponibilidad, podrás realizar el pago correspondiente mediante los métodos habilitados. Tu reserva quedará asegurada tras la confirmación del pago.\r\n\r\n# 8. Recepción de la Confirmación\r\n\r\n✅Recibirás la confirmación oficial de tu reserva, junto con vouchers, comprobantes y detalles finales de tu viaje.\r\n\r\n# 9. Coordinación Previa al Tour\r\n\r\n✅Antes del inicio de la actividad, nuestro equipo se pondrá en contacto contigo para confirmar horarios, punto de encuentro, recomendaciones finales y resolver cualquier consulta de último momento.\r\n\r\n# 10. ¡Disfruta tu Aventura!\r\n\r\n✅Solo queda preparar tu equipaje y vivir una experiencia inolvidable. Nuestro equipo estará atento durante todo el recorrido para brindarte un servicio seguro, cómodo y de calidad.\r\n\r\nEn IntiPath Tours nos comprometemos a ofrecerte una experiencia transparente, segura y bien organizada desde el momento de tu reserva hasta el final de tu viaje.', 'Traveling with us means enjoying carefully planned experiences, with the peace of mind that comes from having a team committed to your comfort, safety, and satisfaction. Our goal is for you to make the most of every moment of your trip while we take care of the details.\r\n\r\n# Personalized Attention\r\n\r\n✅Assistance before, during, and after your trip.\r\n\r\n✅Constant support from our team.\r\n\r\n✅Recommendations tailored to your needs and interests.\r\n\r\n# Flexible Itineraries\r\n✅Travel options for different styles and budgets.\r\n\r\n✅Option to customize certain activities.\r\n\r\n✅Schedules and routes designed to make the most of each destination.\r\n\r\n# Guaranteed Quality\r\n✅Services selected according to high quality standards.\r\n\r\n✅Professional and highly experienced guides.\r\n\r\n✅Safe transportation and reliable operators.\r\n\r\n# Safety and Trust\r\n✅Continuous accompaniment during tours.\r\n\r\n✅ Clear and detailed information before each activity.\r\n\r\n✅ Commitment to the well-being of our travelers.\r\n\r\n# Memorable Experiences\r\n✅ Carefully selected destinations.\r\n\r\n✅ Authentic contact with local culture and nature.\r\n\r\n✅ Unique souvenirs that will make your trip an unforgettable experience.', 'reservar_banner_1781717222.jpg', '¿Necesitas ayuda para elegir el tour perfecto? Te asesoramos gratis.\r\nPara que puedas tener mas información sobre los horarios y itinerarios y fechas disponibles ', 'Need help choosing the perfect tour? We offer free advice.\r\n\r\nWe\'ll provide you with more information about schedules, itineraries, and available dates.', 'Contactar con un  Asesor', 'Contact an Advisor', 'reservar_spec_1781716728.jpg', 'Reserva tu próxima aventura', 'Book your next adventure', 'No esperes más, el Cusco te espera', 'Don\'t wait any longer, Cusco awaits you', 'Ver Tours Disponibles', 'View Available Tours', 'reservar_cta_bg_1781717109.jpg', '', '', NULL, NULL, '', '', '', '#0f9b9e', '3rem', '#444444', '1.1rem');

DROP TABLE IF EXISTS `config_pagos`;
CREATE TABLE `config_pagos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `clave` varchar(50) NOT NULL,
