  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `clave` (`clave`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `configuracion`;
CREATE TABLE `configuracion` (
  `id` int NOT NULL DEFAULT '1',
  `titulo_web` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `meta_descripcion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `logo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `favicon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `header_btn_texto` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'Consultar',
  `header_btn_texto_en` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'Book Now',
  `header_btn_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'contacto.php',
  `header_placeholder_color` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '#0f9b9e',
  `header_placeholder_hover` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '#c6d544',
  `header_placeholder_texto` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'Configura los enlaces desde Gestionar Nosotros',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO `configuracion` (`id`, `titulo_web`, `meta_descripcion`, `logo`, `favicon`, `header_btn_texto`, `header_btn_texto_en`, `header_btn_url`, `header_placeholder_color`, `header_placeholder_hover`, `header_placeholder_texto`) VALUES ('1', 'Inti Path Tours | Agencia de Viajes y Trekking en Cusco', 'Explora Cusco y Machu Picchu con Inti Path Tours. Tours, trekking y aventuras personalizadas con operadores locales expertos.', 'logo-inti-1e06.png', 'fav-inti-293e.ico', 'Mas Información', 'More information', 'contacto.php', '#0f9b9e', '#c6d544', 'Configura los enlaces desde Gestionar Nosotros');

DROP TABLE IF EXISTS `contactos`;
CREATE TABLE `contactos` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Identificador único del mensaje',
  `nombre` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Nombre completo del cliente',
  `email` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Correo electrónico del cliente',
  `telefono` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Número de celular (vital para el bot de WhatsApp)',
  `mensaje` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'La consulta o solicitud de reserva',
  `estado` enum('pendiente','contactado','reservado') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'pendiente' COMMENT 'Para saber si ya atendimos a este cliente',
  `fecha_registro` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Momento exacto en que el cliente llenó el formulario',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

