DROP TABLE IF EXISTS `equipo_guias`;
CREATE TABLE `equipo_guias` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nombre` varchar(255) NOT NULL,
  `rol_es` varchar(150) DEFAULT NULL,
  `rol_en` varchar(150) DEFAULT NULL,
  `foto` varchar(255) DEFAULT NULL,
  `descripcion_es` text,
  `descripcion_en` text,
  `idiomas` varchar(100) DEFAULT NULL,
  `fecha_registro` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `banner_titulo` varchar(255) DEFAULT NULL,
  `banner_titulo_en` varchar(255) DEFAULT NULL,
  `banner_subtitulo` varchar(255) DEFAULT NULL,
  `banner_subtitulo_en` varchar(255) DEFAULT NULL,
  `intro_texto` text,
  `intro_texto_en` text,
  `intro_imagen` varchar(255) DEFAULT NULL,
  `aside_texto` text,
  `aside_texto_en` text,
  `aside_btn` varchar(100) DEFAULT NULL,
  `aside_btn_en` varchar(100) DEFAULT NULL,
  `aside_imagen` varchar(255) DEFAULT NULL,
  `aside_test_tit` varchar(255) DEFAULT NULL,
  `aside_test_tit_en` varchar(255) DEFAULT NULL,
  `aside_test_txt` text,
  `aside_test_txt_en` text,
  `aside_test_img` varchar(255) DEFAULT NULL,
  `aside_test_fecha` varchar(50) DEFAULT NULL,
  `aside_test_fecha_en` varchar(50) DEFAULT NULL,
  `cta_titulo` varchar(255) DEFAULT NULL,
  `cta_titulo_en` varchar(255) DEFAULT NULL,
  `cta_texto` text,
  `cta_texto_en` text,
  `cta_btn` varchar(100) DEFAULT NULL,
  `cta_btn_en` varchar(100) DEFAULT NULL,
  `cta_imagen` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

INSERT INTO `equipo_guias` (`id`, `nombre`, `rol_es`, `rol_en`, `foto`, `descripcion_es`, `descripcion_en`, `idiomas`, `fecha_registro`, `banner_titulo`, `banner_titulo_en`, `banner_subtitulo`, `banner_subtitulo_en`, `intro_texto`, `intro_texto_en`, `intro_imagen`, `aside_texto`, `aside_texto_en`, `aside_btn`, `aside_btn_en`, `aside_imagen`, `aside_test_tit`, `aside_test_tit_en`, `aside_test_txt`, `aside_test_txt_en`, `aside_test_img`, `aside_test_fecha`, `aside_test_fecha_en`, `cta_titulo`, `cta_titulo_en`, `cta_texto`, `cta_texto_en`, `cta_btn`, `cta_btn_en`, `cta_imagen`) VALUES ('1', 'CONFIG_BANNER', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-14 04:48:00', 'Nuestro Equipo', 'Our Team', 'Los expertos detrás de tu aventura', 'The experts behind your adventure', '# Pasión por la Aventura en los Andes\r\nNuestro equipo está formado por guías locales apasionados que han crecido en estas montañas. **Cada paso que damos** es con respeto a nuestra cultura y con la misión de brindarte una experiencia _segura e inolvidable_.', '# Passion for Adventure in the Andes\r\nOur team is made up of passionate local guides who have grown up in these mountains. **Every step we take** is with respect for our culture and with the mission of providing you with a _safe and unforgettable_ experience.', 'banner_intro_1778822405.jpg', 'Un especialista te dará el tiempo necesario para entender tu preferencia y preparar un itinerario que se adecúe a tu presupuesto.', 'Your specialist will give you the necessary time to understand your preference and prepare an itinerary that fits your budget.', '¡CONSULTAR AHORA!', 'CONSULT NOW!', 'specialist_1779738267.jpg', 'Increíble, desafiante, emocionante!!', 'Incredible, challenging, exciting!!', 'La experiencia en la Laguna Humantay fue simplemente increíble. Desde el inicio del tour, todo estuvo muy bien organizado y nuestro guía fue muy amable, atento y siempre dispuesto a ayudarnos y explicarnos sobre la historia y naturaleza del lugar. El paisaje durante la caminata es espectacular y la vista de la laguna realmente supera cualquier expectativa.', 'The experience at Humantay Lagoon was simply incredible. From the start of the tour, everything was very well organized, and our guide was very friendly, attentive, and always willing to help and explain the history and nature of the place. The scenery during the hike is spectacular, and the view of the lagoon truly exceeded all expectations.', 'testimonio_1779738051.jpg', 'Abril, 2026', 'April, 2026', '¿Qué hace que estos viajes sean diferentes?  ', 'What makes these trips different?', 'En IntiPath Tours creemos que viajar es mucho más que visitar un destino; es vivir experiencias auténticas que conectan con la cultura, la naturaleza y las personas. Cada aventura está diseñada para que el viajero descubra paisajes increíbles, comparta momentos únicos y cree recuerdos que permanecerán para siempre.', 'At IntiPath Tours, we believe that travel is much more than visiting a destination; it\'s about experiencing authentic moments that connect you with culture, nature, and people. Each adventure is designed to help travelers discover incredible landscapes, share unique moments, and create memories that will last a lifetime.', '¡Empieza hoy tu próxima gran aventura!', 'Start your next great adventure today!', 'cta_bg_1779738051.jpg');

