  `banner_subtitulo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'Tu tranquilidad es nuestra prioridad',
  `banner_subtitulo_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'Your peace of mind is our priority',
  `banner_titulo_size` int DEFAULT '64',
  `banner_subtitulo_size` int DEFAULT '24',
  `banner_color_titulo` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '#0f9b9e',
