  `aside_texto` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `aside_texto_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `aside_btn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'Ver Detalles',
  `aside_btn_en` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'See Details',
  `aside_imagen` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'hero_tours.jpg',
  `aside_color_titulo` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '#0f9b9e',
