INSERT INTO `garantia` (`id`, `banner_titulo`, `banner_titulo_en`, `banner_subtitulo`, `banner_subtitulo_en`, `banner_titulo_size`, `banner_subtitulo_size`, `banner_color_titulo`, `banner_color_subtitulo`, `banner_imagen`, `intro_titulo`, `intro_titulo_en`, `intro_titulo_size`, `intro_color_titulo`, `intro_texto`, `intro_texto_en`, `intro_color_texto`, `cta_titulo`, `cta_titulo_en`, `cta_texto`, `cta_texto_en`, `cta_btn`, `cta_btn_en`, `cta_imagen`, `cta_color_titulo`, `cta_color_texto`, `cta_color_btn`, `cta_color_btn_hover`, `aside_texto`, `aside_texto_en`, `aside_btn`, `aside_btn_en`, `aside_imagen`, `aside_color_titulo`, `aside_color_btn`, `aside_color_btn_hover`, `aside_test_tit`, `aside_test_tit_en`, `aside_test_txt`, `aside_test_txt_en`, `aside_test_img`, `aside_test_fecha`, `aside_test_fecha_en`) VALUES ('1', 'Garantía de Calidad', 'Quality Guarantee', 'Tu tranquilidad es nuestra prioridad', 'Your peace of mind is our priority', '64', '24', '#ffffff', '#f1f1f1', 'garantia_banner_1781709524.png', 'Nuestro Compromiso', 'Our Commitment', '40', '#0f9b9e', '# Tu tranquilidad es nuestra prioridad\r\nServicio confiable y atención de calidad.\r\n\r\n- Información clara y transparente.\r\n- Soporte continuo durante toda la experiencia.\r\n- Coordinación eficiente de cada actividad.\r\n- Compromiso con la satisfacción de nuestros viajeros.\r\n\r\n# Porque elegirnos para tu viaje \r\n- En Inti Path Tours nos apasiona crear experiencias auténticas e inolvidables en Cusco. Nuestro compromiso es brindar un servicio de calidad, atención personalizada y la seguridad que cada viajero merece.', '# Your peace of mind is our priority\r\nReliable service and quality attention.\r\n\r\n- Clear and transparent information.\r\n\r\n- Continuous support throughout your experience.\r\n\r\n- Efficient coordination of every activity.\r\n\r\n- Commitment to our travelers\' satisfaction.\r\n\r\n# Why choose us for your trip?\r\n- At Inti Path Tours, we are passionate about creating authentic and unforgettable experiences in Cusco. Our commitment is to provide quality service, personalized attention, and the safety that every traveler deserves.', '#555555', '¿Listo para tu aventura?', 'Ready for your adventure?', 'Vive experiencias únicas con nosotros, descubre nuevos destinos y disfruta cada momento.', 'Live unique experiences with us, explore new destinations, and enjoy every moment.', 'Contáctanos', 'Contact Us', 'garantia_cta_bg_1781708681.jpg', '#ffffff', '#ffffff', '#0f9b9e', '#c6d544', 'Nosotros te ayudamos en tu viaje ', 'We help you on your journey', 'Mas información', 'More information', 'garantia_aside_1781708033.webp', '#0f9b9e', '#0f9b9e', '#c6d544', '¡Excelente City Tour por Cusco!', 'Excellent City Tour of Cusco!', '\"¡Excelente recorrido por la ciudad de Cusco! Conocimos la Plaza de Armas, San Blas, Qoricancha y el Mercado de San Pedro. El guía fue muy atento y aprendimos mucho sobre la historia y cultura cusqueña. ¡Totalmente recomendado!\"', '\"Excellent tour of Cusco! We visited the Plaza de Armas, San Blas, Qoricancha, and the San Pedro Market. The guide was very attentive, and we learned a lot about Cusco\'s history and culture. Highly recommended!\"', 'garantia_testimonio_1781708033.jpg', 'Mayo 2026', 'May 2026');

DROP TABLE IF EXISTS `garantia_imagenes`;
