) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `info_previa` (`id`, `banner_titulo`, `banner_titulo_en`, `banner_subtitulo`, `banner_subtitulo_en`, `intro_texto`, `intro_texto_en`, `intro_imagen`, `aside_texto`, `aside_texto_en`, `aside_btn`, `aside_btn_en`, `aside_imagen`, `cta_titulo`, `cta_titulo_en`, `cta_texto`, `cta_texto_en`, `cta_btn`, `cta_btn_en`, `cta_imagen`, `aside_test_tit`, `aside_test_tit_en`, `aside_test_txt`, `aside_test_txt_en`, `aside_test_img`, `aside_test_fecha`, `aside_test_fecha_en`, `color_titulo`, `tamano_titulo`, `color_texto`, `tamano_texto`) VALUES ('1', 'Descubre tu próxima aventura', 'Discover your next adventure', 'Viaja con seguridad y confianza', 'Travel with safety and confidence', 'Viajar con nosotros significa disfrutar de experiencias cuidadosamente organizadas, con la tranquilidad de contar con un equipo comprometido con tu comodidad, seguridad y satisfacción. Nuestro objetivo es que aproveches cada momento del viaje mientras nosotros nos encargamos de los detalles.\r\n\r\n# Atención Personalizada\r\n\r\n✅Asistencia antes, durante y después de tu viaje.\r\n✅Soporte constante por parte de nuestro equipo.\r\n✅Recomendaciones adaptadas a tus necesidades e intereses.\r\n\r\n# Itinerarios Flexibles\r\n✅Opciones de viaje para diferentes estilos y presupuestos.\r\n✅Posibilidad de personalizar ciertas actividades.\r\n✅Horarios y recorridos diseñados para aprovechar mejor cada destino.\r\n\r\n# Calidad Garantizada\r\n✅Servicios seleccionados bajo altos estándares de calidad.\r\n✅Guías profesionales y con amplia experiencia.\r\n✅Transporte seguro y operadores confiables.\r\n\r\n# Seguridad y Confianza\r\n✅Acompañamiento permanente durante los tours.\r\n✅Información clara y detallada antes de cada actividad.\r\n✅Compromiso con el bienestar de nuestros viajeros.\r\n\r\n# Experiencias Memorables\r\n✅Destinos cuidadosamente seleccionados.\r\n✅Contacto auténtico con la cultura y naturaleza local.\r\n✅Recuerdos únicos que harán de tu viaje una experiencia inolvidable.', 'Traveling with us means enjoying carefully planned experiences, with the peace of mind that comes from having a team committed to your comfort, safety, and satisfaction. Our goal is for you to make the most of every moment of your trip while we take care of the details.\r\n\r\n# Personalized Attention\r\n\r\n✅Assistance before, during, and after your trip.\r\n\r\n✅Constant support from our team.\r\n\r\n✅Recommendations tailored to your needs and interests.\r\n\r\n# Flexible Itineraries\r\n✅Travel options for different styles and budgets.\r\n\r\n✅Option to customize certain activities.\r\n\r\n✅Schedules and routes designed to make the most of each destination.\r\n\r\n# Guaranteed Quality\r\n✅Services selected according to high quality standards.\r\n\r\n✅Professional and highly experienced guides.\r\n\r\n✅Safe transportation and reliable operators.\r\n\r\n# Safety and Trust\r\n✅Continuous accompaniment during tours.\r\n\r\n✅ Clear and detailed information before each activity.\r\n\r\n✅ Commitment to the well-being of our travelers.\r\n\r\n# Memorable Experiences\r\n✅ Carefully selected destinations.\r\n\r\n✅ Authentic contact with local culture and nature.\r\n\r\n✅ Unique souvenirs that will make your trip an unforgettable experience.', 'info_previa_banner_1779190255.jpg', 'Nuestro equipo de especialistas está listo para asesorarte en cada paso de tu viaje. Recibirás atención personalizada y soluciones adaptadas a tus necesidades.', 'Our team of specialists is ready to guide you through every step of your journey. You will receive personalized attention and solutions tailored to your needs.', 'Consultar Ahora', 'Consult Now', 'info_previa_spec_1779748753.jpg', 'Planifica tu viaje con nosotros', 'Plan your trip with us', ' Organiza cada detalle de tu próxima aventura de manera sencilla y segura. Nuestro equipo te acompaña en todo el proceso para que disfrutes sin preocupaciones.', 'Organize every detail of your next adventure easily and safely. Our team supports you throughout the process so you can enjoy without worries.', 'Empezar Planificación', 'Start Planning', 'info_previa_cta_bg_1779190960.jpg', '', '', NULL, NULL, '', '', '', '', '', '', '');

DROP TABLE IF EXISTS `info_viaje`;
CREATE TABLE `info_viaje` (
  `id` int NOT NULL AUTO_INCREMENT,
  `tour_id` int DEFAULT NULL,
  `titulo` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `imagen` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `enlace` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tour_id` (`tour_id`),
  CONSTRAINT `info_viaje_ibfk_1` FOREIGN KEY (`tour_id`) REFERENCES `tours` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

DROP TABLE IF EXISTS `libro_reclamaciones`;
CREATE TABLE `libro_reclamaciones` (
  `id` int NOT NULL AUTO_INCREMENT,
  `codigo_reclamo` varchar(20) DEFAULT NULL,
  `nombre` varchar(100) DEFAULT NULL,
  `tipo_documento` varchar(20) DEFAULT NULL,
  `numero_documento` varchar(20) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `telefono` varchar(20) DEFAULT NULL,
  `domicilio` text,
  `tipo_bien` enum('Producto','Servicio') DEFAULT NULL,
  `monto_reclamado` decimal(10,2) DEFAULT NULL,
  `descripcion_bien` text,
  `detalle_reclamo` text,
  `pedido_cliente` text,
  `estado` enum('Iniciado','En Trámite','Finalizado') DEFAULT 'Iniciado',
  `fecha_registro` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `codigo_reclamo` (`codigo_reclamo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `licencias`;
CREATE TABLE `licencias` (
  `id` int NOT NULL AUTO_INCREMENT,
  `titulo` varchar(255) NOT NULL,
  `imagen` varchar(255) NOT NULL,
  `orden` int DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

