DROP TABLE IF EXISTS `plantilla_pdf`;
CREATE TABLE `plantilla_pdf` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nombre` varchar(100) NOT NULL,
  `contenido_html` longtext,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

INSERT INTO `plantilla_pdf` (`id`, `nombre`, `contenido_html`, `created_at`, `updated_at`) VALUES ('1', 'Plantilla por defecto', '<html><head><style>\r\nbody { font-family: \"Segoe UI\", Arial, sans-serif; font-size: 12px; color: #333; margin: 0; padding: 30px; }\r\n.header { text-align: center; border-bottom: 3px solid #E8AC18; padding-bottom: 20px; margin-bottom: 20px; }\r\n.header img { max-width: 200px; }\r\n.header h1 { color: #15305D; font-size: 20px; margin: 10px 0 0 0; }\r\n.header p { color: #666; font-size: 11px; margin: 2px 0; }\r\n.codigo-badge { background: #15305D; color: #fff; padding: 8px 25px; font-size: 16px; font-weight: bold; text-align: center; display: inline-block; border-radius: 4px; margin: 10px 0; }\r\n.section { margin: 15px 0; }\r\n.section h3 { background: #f0f0f0; color: #15305D; padding: 8px 12px; font-size: 12px; text-transform: uppercase; margin: 0 0 10px 0; border-left: 4px solid #E8AC18; }\r\ntable { width: 100%; border-collapse: collapse; margin: 5px 0; }\r\nth { background: #15305D; color: #fff; padding: 6px 8px; text-align: left; font-size: 11px; }\r\ntd { padding: 6px 8px; border-bottom: 1px solid #eee; font-size: 11px; }\r\ntr:nth-child(even) { background: #f9f9f9; }\r\n.total-row { font-weight: bold; background: #f5f5f5; }\r\n.pago-info { background: #f8fbff; border: 1px solid #d1e3fa; padding: 12px; border-radius: 4px; margin: 10px 0; }\r\n.footer { text-align: center; border-top: 2px solid #E8AC18; padding-top: 15px; margin-top: 25px; font-size: 10px; color: #888; }\r\n.footer strong { color: #15305D; }\r\n</style></head><body>\r\n<div class=\"header\">\r\n<img src=\"{logo}\" width=\"180\">\r\n<h1>SOLICITUD DE RESERVA</h1>\r\n<p>IntiPath Tours - Cusco, Peru</p>\r\n</div>\r\n<div style=\"text-align:center;\">\r\n<span class=\"codigo-badge\">RESERVA #{codigo}</span>\r\n</div>\r\n<div class=\"section\">\r\n<h3>Datos del Tour</h3>\r\n<table>\r\n<tr><td width=\"120\"><strong>Tour:</strong></td><td>{tour}</td></tr>\r\n<tr><td><strong>Fecha Viaje:</strong></td><td>{fecha_viaje}</td></tr>\r\n<tr><td><strong>Duracion:</strong></td><td>{duracion}</td></tr>\r\n</table>\r\n</div>\r\n<div class=\"section\">\r\n<h3>Pasajeros</h3>\r\n<table>\r\n<thead><tr><th>#</th><th>Tipo</th><th>Nombres</th><th>Apellidos</th><th>Documento</th><th>Pais</th></tr></thead>\r\n<tbody>\r\n{pasajeros}\r\n</tbody>\r\n</table>\r\n</div>\r\n<div class=\"section\">\r\n<h3>Contacto</h3>\r\n<table>\r\n<tr><td width=\"120\"><strong>Email:</strong></td><td>{email}</td></tr>\r\n<tr><td><strong>Telefono:</strong></td><td>{telefono}</td></tr>\r\n<tr><td><strong>WhatsApp:</strong></td><td>{whatsapp}</td></tr>\r\n<tr><td><strong>Mensaje:</strong></td><td>{mensaje}</td></tr>\r\n</table>\r\n</div>\r\n<div class=\"section\">\r\n<h3>Detalle de Pago</h3>\r\n<div class=\"pago-info\">\r\n<table>\r\n<tr><td><strong>Precio por adulto:</strong></td><td align=\"right\">{precio_adulto}</td></tr>\r\n<tr><td><strong>Total viaje:</strong></td><td align=\"right\">{total}</td></tr>\r\n<tr><td style=\"border-top:1px solid #d1e3fa;\"><strong>Adelanto:</strong></td><td style=\"border-top:1px solid #d1e3fa;\" align=\"right\">{adelanto}</td></tr>\r\n<tr><td><strong>Saldo en Cusco:</strong></td><td align=\"right\">{saldo}</td></tr>\r\n<tr class=\"total-row\"><td><strong>Metodo de pago:</strong></td><td align=\"right\">{metodo_pago}</td></tr>\r\n<tr><td><strong>Estado:</strong></td><td align=\"right\">{estado}</td></tr>\r\n</table>\r\n</div>\r\n</div>\r\n<div class=\"section\">\r\n<h3>Datos Bancarios</h3>\r\n<table>\r\n<tr><td><strong>Banco:</strong></td><td>BCP</td></tr>\r\n<tr><td><strong>Titular:</strong></td><td>IntiPath Tours Peru S.A.C.</td></tr>\r\n<tr><td><strong>Cuenta Soles:</strong></td><td>305-9876543-0-00</td></tr>\r\n<tr><td><strong>Cuenta Dolares:</strong></td><td>305-9876544-0-55</td></tr>\r\n<tr><td><strong>CCI:</strong></td><td>00230519876543000055</td></tr>\r\n</table>\r\n</div>\r\n<div class=\"footer\">\r\n<img src=\"{logo}\" width=\"100\"><br>\r\n<strong>IntiPath Tours</strong> - Cusco, Peru<br>\r\n{telefono_contacto} | {email_contacto} | {web}<br>\r\n<small>* Este documento es generado automaticamente. Valido como solicitud de reserva.</small>\r\n</div>\r\n</body></html>', '2026-05-29 12:02:01', '2026-05-29 12:02:01');

DROP TABLE IF EXISTS `politica_privacidad`;
CREATE TABLE `politica_privacidad` (
  `id` int NOT NULL AUTO_INCREMENT,
  `contenido` text,
  `imagen` varchar(255) DEFAULT NULL,
  `ultima_actualizacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

INSERT INTO `politica_privacidad` (`id`, `contenido`, `imagen`, `ultima_actualizacion`) VALUES ('1', '# POLÍTICA DE PRIVACIDAD\r\n## 1. IDENTIDAD DEL RESPONSABLE\r\nLa presente Política de Privacidad regula el tratamiento de datos personales recopilados por Inti Path Tours, con domicilio en APV Coviduc Lote A6 – Paradero Sol de Oro - San Sebastián - Cusco, identificada con RUC 20615665984.\r\nPara cualquier consulta, puede contactarnos a través \r\n- correo:intipathtourstrekkinperu@gmail.com.\r\n## 2. DATOS PERSONALES QUE RECOPILAMOS\r\nRecopilamos información necesaria para brindarle nuestros servicios, tales como:\r\n- Nombres y apellidos\r\n- Documento de identidad o pasaporte\r\n- Nacionalidad\r\n- Número de teléfono y correo electrónico\r\n- Información de viaje (fechas, destinos, preferencias)\r\n- Datos de pago (cuando corresponda)\r\n## 3. FINALIDAD DEL TRATAMIENTO DE DATOS\r\nLos datos personales serán utilizados para:\r\n- Gestionar reservas de tours, paquetes turísticos y servicios relacionados.\r\n- Coordinar transporte, hospedaje y actividades turísticas.\r\n- Contactarlo para confirmar servicios o brindar asistencia.\r\n- Emitir comprobantes de pago.\r\n- Cumplir obligaciones legales ante entidades como la SUNAT.\r\n- Enviar información relevante sobre nuestros servicios (previo consentimiento).\r\n## 4. PROTECCIÓN DE LA INFORMACIÓN\r\nInti Path Tours adopta medidas de seguridad técnicas y organizativas para proteger sus datos personales, evitando su pérdida, uso indebido, acceso no autorizado o divulgación.\r\n## 5. COMPARTICIÓN DE DATOS\r\nSus datos podrán ser compartidos únicamente cuando sea necesario con:\r\n- Hoteles, operadores turísticos y empresas de transporte.\r\n- Entidades financieras para procesar pagos.\r\n- Autoridades competentes cuando lo exija la ley.\r\nEn ningún caso se venderá o compartirá su información con fines comerciales sin su consentimiento.\r\n## 6. DERECHOS DEL TITULAR DE LOS DATOS\r\nUsted puede ejercer sus derechos de:\r\n- Acceso\r\n- Rectificación\r\n- Cancelación\r\n- Oposición\r\nPara ello, puede enviar una solicitud a nuestro correo electrónico: intipathtourstrekkinperu@gmail.com.\r\n## 7. USO DE COOKIES\r\n- Nuestro sitio web puede utilizar cookies para mejorar la experiencia del usuario. \r\n- Usted puede configurar su navegador para rechazarlas si lo desea.\r\n## 8. CONSENTIMIENTO\r\n- Al proporcionar sus datos personales, usted autoriza a Inti Path Tours a tratarlos conforme a esta Política de Privacidad.\r\n## 9. MODIFICACIONES\r\n- Nos reservamos el derecho de actualizar esta Política de Privacidad en cualquier momento Cualquier cambio será publicado oportunamente.\r\n## 10. BASE LEGAL\r\n- Esta política se rige por la Ley N.° 29733 – Ley de Protección de Datos Personales del Perú.', 'banner_priv_1778949127.png', '2026-05-16 11:32:07');

