  `orden` int DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO `porque_nosotros` (`id`, `titulo`, `descripcion`, `imagen`, `orden`) VALUES ('13', '¿Por qué elegirnos?', 'Contamos con guías profesionales, itinerarios cuidadosamente planificados.', 'pq_13_1775247031.jpeg', '1');
INSERT INTO `porque_nosotros` (`id`, `titulo`, `descripcion`, `imagen`, `orden`) VALUES ('15', 'Guías expertos y locales', 'Te acompañamos con guías expertos, priorizando siempre tu seguridad y bienestar.', 'pq_15_1775247117.jpeg', '2');
