DROP TABLE IF EXISTS `preguntas_frecuentes`;
CREATE TABLE `preguntas_frecuentes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `pregunta` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `pregunta_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `respuesta` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `respuesta_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `orden` int DEFAULT '0',
  `estado` tinyint DEFAULT '1',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO `preguntas_frecuentes` (`id`, `pregunta`, `pregunta_en`, `respuesta`, `respuesta_en`, `orden`, `estado`) VALUES ('1', '¿Cómo prevenir el mal de altura en Cusco?', 'How to prevent altitude sickness in Cusco?', 'Si vienes a Cusco desde una ciudad de menor altitud o desde el extranjero, es importante descansar las primeras horas, mantenerte bien hidratado y comer ligero para ayudar a tu cuerpo a adaptarse. También se recomienda tomar mate de coca, evitar comidas pesadas y alcohol el primer día, y llevar contigo agua, snacks ligeros y los medicamentos que tu médico te haya indicado para prevenir el mal de altura.', 'We recommend resting on the first day, drinking plenty of water, avoiding heavy meals, and trying the traditional coca tea. At IntiPath Tours, we suggest arriving at least two days before starting any hike.', '1', '1');
INSERT INTO `preguntas_frecuentes` (`id`, `pregunta`, `pregunta_en`, `respuesta`, `respuesta_en`, `orden`, `estado`) VALUES ('2', '¿Qué ayuda al mal de altura en Cusco?', '', 'Para prevenir o aliviar el mal de altura en Cusco, se recomienda descansar al llegar, beber suficiente agua, comer ligero y evitar el alcohol el primer día. También puede ayudar tomar mate de coca, consumir snacks suaves y llevar los medicamentos que tu médico te haya recomendado para adaptarte mejor a la altitud.', '', '2', '1');
INSERT INTO `preguntas_frecuentes` (`id`, `pregunta`, `pregunta_en`, `respuesta`, `respuesta_en`, `orden`, `estado`) VALUES ('3', '¿Cómo evitar el mal de altura en Perú?', NULL, 'La clave es el ascenso gradual. Si viajas desde la costa, tómate un tiempo en ciudades de altura intermedia y evita el esfuerzo físico intenso durante las primeras 24 horas.', NULL, '3', '1');
INSERT INTO `preguntas_frecuentes` (`id`, `pregunta`, `pregunta_en`, `respuesta`, `respuesta_en`, `orden`, `estado`) VALUES ('4', '¿Cuáles son los meses más fríos en Cusco, Perú?', '', 'los meses más fríos suelen ser junio, julio y agosto, especialmente durante la temporada seca. Durante este periodo, las mañanas y noches pueden ser bastante frías, con temperaturas que en algunas zonas llegan cerca de los 0 °C o incluso menos, mientras que en el día el clima suele ser más templado y soleado.', '', '4', '1');
INSERT INTO `preguntas_frecuentes` (`id`, `pregunta`, `pregunta_en`, `respuesta`, `respuesta_en`, `orden`, `estado`) VALUES ('5', '¿Cuál es la mejor caminata a Machu Picchu?', '', 'la caminata más famosa y considerada la mejor para llegar a Machu Picchu es el Camino Inca Clásico, porque combina historia, paisajes andinos y el ingreso a Machupicchu por la Puerta del Sol (Inti Punku).', '', '5', '1');
INSERT INTO `preguntas_frecuentes` (`id`, `pregunta`, `pregunta_en`, `respuesta`, `respuesta_en`, `orden`, `estado`) VALUES ('6', '¿Cuál es el mejor mes para ir a Machu Picchu?', '', ' Los meses de junio, julio y agosto ofrecen el clima más estable. Ten en cuenta que es temporada alta, por lo que la afluencia de personas es máxima y los boletos deben comprarse con mucha anticipación.', '', '6', '1');
INSERT INTO `preguntas_frecuentes` (`id`, `pregunta`, `pregunta_en`, `respuesta`, `respuesta_en`, `orden`, `estado`) VALUES ('7', '¿Cuál es mejor, Camino Inca o Camino a Salkantay?', '', 'No hay una ruta \"mejor\" que otra; todo depende del tipo de experiencia que busques. El Camino Inca es ideal si buscas historia, cultura y ruinas arqueológicas, mientras que el Salkantay Trek es perfecto para los amantes de la naturaleza salvaje, paisajes de alta montaña y menos aglomeración.', '', '7', '1');
INSERT INTO `preguntas_frecuentes` (`id`, `pregunta`, `pregunta_en`, `respuesta`, `respuesta_en`, `orden`, `estado`) VALUES ('8', '¿Se puede ir de excursión a Machu Picchu en un día?', '', 'Lo más común es salir desde Cusco o el Valle Sagrado muy temprano , viajar en carro o tren hasta Aguas Calientes, y luego subir en bus hasta la entrada de Machu Picchu. Esto permite hacer la visita y regresar el mismo día, aunque es un recorrido largo e intenso.', '', '8', '1');
INSERT INTO `preguntas_frecuentes` (`id`, `pregunta`, `pregunta_en`, `respuesta`, `respuesta_en`, `orden`, `estado`) VALUES ('9', '¿Es peligrosa la caminata a Salkantay?', '', 'La caminata a Salkantay no es peligrosa, pero sí es una ruta exigente que requiere buena condición física y una adecuada aclimatación a la altura, el recorrido incluye pasos altos de montaña (como el Abra Salkantay), frío intenso en zonas elevadas y cambios de clima, por lo que puede ser difícil si no estás preparado.', '', '9', '1');
INSERT INTO `preguntas_frecuentes` (`id`, `pregunta`, `pregunta_en`, `respuesta`, `respuesta_en`, `orden`, `estado`) VALUES ('10', '¿Cuál es el mejor mes para recorrer el Camino Inca?', '', 'El mejor momento para recorrer el Camino Inca es durante la temporada seca, entre mayo y septiembre. En estos meses hay menos lluvias, los senderos están en mejores condiciones y las vistas de los paisajes andinos son más despejadas.', '', '10', '1');
INSERT INTO `preguntas_frecuentes` (`id`, `pregunta`, `pregunta_en`, `respuesta`, `respuesta_en`, `orden`, `estado`) VALUES ('11', '¿Es difícil la caminata a Salkantay?', NULL, 'Se considera una caminata de nivel moderado a desafiante debido a la altitud (4,630m). Requiere una condición física aceptable y, sobre todo, una buena aclimatación previa.', NULL, '11', '1');
INSERT INTO `preguntas_frecuentes` (`id`, `pregunta`, `pregunta_en`, `respuesta`, `respuesta_en`, `orden`, `estado`) VALUES ('12', '¿Qué altura tiene el Camino Inca?', '', 'El Camino Inca alcanza distintas altitudes a lo largo de la ruta. Su punto más alto es el Abra Warmiwañusca (Paso de la Mujer Muerta), que llega aproximadamente a los 4,215 metros sobre el nivel del mar.', '', '12', '1');
INSERT INTO `preguntas_frecuentes` (`id`, `pregunta`, `pregunta_en`, `respuesta`, `respuesta_en`, `orden`, `estado`) VALUES ('13', '¿Qué altura tiene el Abra Salkantay?', NULL, 'El paso más alto del Salkantay Trek se encuentra a 4,630 metros de altura, ofreciendo una vista espectacular del nevado Salkantay.', NULL, '13', '1');
INSERT INTO `preguntas_frecuentes` (`id`, `pregunta`, `pregunta_en`, `respuesta`, `respuesta_en`, `orden`, `estado`) VALUES ('14', '¿Qué tan difícil es la caminata al paso de la Mujer Muerta?', NULL, 'Es el tramo más duro del Camino Inca debido a la subida empinada. Se recomienda subir despacio, a su propio ritmo, y usar bastones de trekking para apoyo.', NULL, '14', '1');
INSERT INTO `preguntas_frecuentes` (`id`, `pregunta`, `pregunta_en`, `respuesta`, `respuesta_en`, `orden`, `estado`) VALUES ('15', '¿Qué tan frío es el viaje a Salkantay?', '', 'El Salkantay Trek tiene un clima extremo. En las zonas altas (Abra Salkantay, a 4,630 m) y Soraypampa, el clima es gélido: las noches descienden hasta los -10 °C y durante el día ronda los 8 °C a 15 °C. Sin embargo, al descender hacia la ceja de selva, el ambiente se vuelve cálido y tropical.', '', '15', '1');
INSERT INTO `preguntas_frecuentes` (`id`, `pregunta`, `pregunta_en`, `respuesta`, `respuesta_en`, `orden`, `estado`) VALUES ('16', '¿Qué debo empacar para el Camino Inca?', '', 'Para el Camino Inca debes empacar solo lo esencial debido a que el peso es limitado y la caminata es exigente. Se recomienda llevar ropa cómoda y ligera para el día, así como prendas abrigadoras para las noches frías en la montaña. Es importante incluir una casaca impermeable o poncho de lluvia, zapatos de trekking ya usados, gorro para el sol y para el frío, además de bloqueador solar y lentes de sol.', '', '16', '1');
INSERT INTO `preguntas_frecuentes` (`id`, `pregunta`, `pregunta_en`, `respuesta`, `respuesta_en`, `orden`, `estado`) VALUES ('17', '¿Se necesita un permiso para la caminata a Salkantay?', '', 'No se necesita un permiso oficial del gobierno(como el del Camino Inca) para recorrer la ruta. Solo necesitarás tu boleto de ingreso a Machu Picchu, el boleto de entrada a la zona de Salkantay (pagado en el mismo punto de control) y tu pasaporte o documento de identidad.', '', '17', '1');
INSERT INTO `preguntas_frecuentes` (`id`, `pregunta`, `pregunta_en`, `respuesta`, `respuesta_en`, `orden`, `estado`) VALUES ('18', '¿Es difícil el Camino Inca?', NULL, 'Es moderado. Lo más desafiante son las escaleras de piedra y la altitud, pero con un ritmo constante y el apoyo de nuestros porteadores, es totalmente realizable.', NULL, '18', '1');
INSERT INTO `preguntas_frecuentes` (`id`, `pregunta`, `pregunta_en`, `respuesta`, `respuesta_en`, `orden`, `estado`) VALUES ('19', '¿Cómo puedo prepararme para la caminata a Salkantay?', NULL, 'Recomendamos realizar caminatas cortas en las semanas previas, ejercicios cardiovasculares y, sobre todo, estar en Cusco 2 o 3 días antes para aclimatar el cuerpo.', NULL, '19', '1');
INSERT INTO `preguntas_frecuentes` (`id`, `pregunta`, `pregunta_en`, `respuesta`, `respuesta_en`, `orden`, `estado`) VALUES ('20', '¿Qué condición física se debo tener para recorrer los tours con mas exigencia ?', '', 'Para realizar los tours de mayor exigencia en los Andes (como el Ausangate Trek,  el Salkantay Trek o inca jungle) Se requiere una excelente condición física, resistencia cardiovascular comprobada, y aclimatación.', '', '20', '1');

DROP TABLE IF EXISTS `reservas`;
CREATE TABLE `reservas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `codigo` varchar(20) NOT NULL,
  `nombre` varchar(100) DEFAULT NULL,
  `apellido` varchar(100) DEFAULT NULL,
  `id_tour` int NOT NULL,
  `fecha_viaje` date NOT NULL,
  `pais` varchar(100) DEFAULT NULL,
  `email` varchar(200) NOT NULL,
  `telefono` varchar(50) DEFAULT NULL,
  `whatsapp` varchar(50) DEFAULT NULL,
  `mensaje` text,
  `total_adultos` int DEFAULT '0',
  `total_ninos` int DEFAULT '0',
  `precio_adulto` decimal(10,2) DEFAULT '0.00',
  `monto_total` decimal(10,2) DEFAULT '0.00',
  `adelanto` decimal(10,2) DEFAULT '0.00',
  `saldo` decimal(10,2) DEFAULT '0.00',
  `metodo_pago` varchar(50) DEFAULT NULL,
  `estado` varchar(20) DEFAULT 'pendiente',
  `pdf_generado` tinyint(1) DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

