  `tarjeta1_titulo` varchar(255) DEFAULT '',
  `tarjeta1_titulo_en` varchar(255) DEFAULT '',
  `tarjeta1_enlace` varchar(500) DEFAULT '',
  `tarjeta1_imagen` varchar(255) DEFAULT '',
  `tarjeta2_titulo` varchar(255) DEFAULT '',
  `tarjeta2_titulo_en` varchar(255) DEFAULT '',
  `tarjeta2_enlace` varchar(500) DEFAULT '',
  `tarjeta2_imagen` varchar(255) DEFAULT '',
  `tarjeta3_titulo` varchar(255) DEFAULT '',
  `tarjeta3_titulo_en` varchar(255) DEFAULT '',
  `tarjeta3_enlace` varchar(500) DEFAULT '',
  `tarjeta3_imagen` varchar(255) DEFAULT '',
  `tarjeta4_titulo` varchar(255) DEFAULT '',
  `tarjeta4_titulo_en` varchar(255) DEFAULT '',
  `tarjeta4_enlace` varchar(500) DEFAULT '',
