INSERT INTO `reservas_info` (`id`, `banner_titulo`, `banner_titulo_en`, `banner_subtitulo`, `banner_subtitulo_en`, `banner_imagen`, `tarjeta1_titulo`, `tarjeta1_titulo_en`, `tarjeta1_enlace`, `tarjeta1_imagen`, `tarjeta2_titulo`, `tarjeta2_titulo_en`, `tarjeta2_enlace`, `tarjeta2_imagen`, `tarjeta3_titulo`, `tarjeta3_titulo_en`, `tarjeta3_enlace`, `tarjeta3_imagen`, `tarjeta4_titulo`, `tarjeta4_titulo_en`, `tarjeta4_enlace`, `tarjeta4_imagen`, `motiva_titulo`, `motiva_titulo_en`, `motiva_texto`, `motiva_texto_en`, `motiva_cta`, `motiva_cta_en`, `motiva_fondo`, `color_titulo`, `tamano_titulo`, `fuente_titulo`, `color_texto`, `tamano_texto`, `fuente_texto`) VALUES ('1', 'Reserva tu Viaje', 'Book Your Trip', 'Explora Machu Picchu y el Valle Sagrado con los mejores guias', 'Explore Machu Picchu and the Sacred Valley with the best guides', 'reservas_banner_1786401032.jpg', 'Terminos y Condiciones', 'Terms and Conditions', 'terminos.php', 't1.jpg', 'Como Hacer una Reserva', 'How to Make a Reservation', 'reservar.php', 't2.jpg', 'Alquiler Opcional', 'Optional Equipment Rental', 'alquiler.php', 't3.jpg', 'Calendarios de Excursiones', 'Excursion Calendars', 'calendario.php', 't4.jpg', 'Tu aventura comienza aqui', 'Your adventure starts here', 'Reserva ahora y vive una experiencia inolvidable en el Peru. Nuestro equipo de guias certificados te acompanara en cada paso de tu aventura.', 'Book now and live an unforgettable experience in Peru. Our team of certified guides will accompany you every step of your adventure.', 'Reserva Ahora', 'Book Now', 'motiva.jpg', '#0f9b9e', '3rem', 'Poppins', '#444444', '1.1rem', 'Poppins');

DROP TABLE IF EXISTS `secciones_index`;
CREATE TABLE `secciones_index` (
  `id` int NOT NULL AUTO_INCREMENT,
  `seccion` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `activo` tinyint(1) DEFAULT '1',
  `orden` int DEFAULT '0',
  `icono` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '',
  `titulo_es` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `titulo_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `subtitulo_es` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `subtitulo_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `texto_es` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `texto_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `boton_texto_es` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '',
  `boton_texto_en` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '',
  `boton_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '',
  `color_titulo` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '',
  `color_texto` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '',
  `tamano_titulo` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '',
  `tamano_texto` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO `secciones_index` (`id`, `seccion`, `activo`, `orden`, `icono`, `titulo_es`, `titulo_en`, `subtitulo_es`, `subtitulo_en`, `texto_es`, `texto_en`, `boton_texto_es`, `boton_texto_en`, `boton_url`, `color_titulo`, `color_texto`, `tamano_titulo`, `tamano_texto`) VALUES ('1', 'intro', '1', '0', '', 'Explora el Corazón de los Andes & <span>Machu Picchu2222</span> con Expertos en Viajes de Aventura', 'Explore the Heart of the Andes & <span>Machu Picchu</span> with Adventure Travel Experts', '', '', 'En <strong>IntiPath Tours</strong>, somos especialistas en guiar experiencias auténticas y personalizadas hacia las maravillas del Perú. Nos enfocamos en ofrecer rutas óptimas y servicios de alta calidad que se ajustan perfectamente a tus sueños de viaje. Con un equipo apasionado y guías locales, te desafiamos a <strong>explorar nuevos lugares y culturas</strong>, garantizando una inmersión cultural profunda y recuerdos que durarán toda la vida.', 'At <strong>IntiPath Tours</strong>, we specialize in guiding authentic and personalized experiences towards the wonders of Peru. We focus on offering optimal routes and high-quality services that perfectly fit your travel dreams. With a passionate team and local guides, we challenge you to <strong>explore new places and cultures</strong>, guaranteeing a deep cultural immersion and memories that will last a lifetime.', '', '', '', '#000000', '#000000', '', '');
INSERT INTO `secciones_index` (`id`, `seccion`, `activo`, `orden`, `icono`, `titulo_es`, `titulo_en`, `subtitulo_es`, `subtitulo_en`, `texto_es`, `texto_en`, `boton_texto_es`, `boton_texto_en`, `boton_url`, `color_titulo`, `color_texto`, `tamano_titulo`, `tamano_texto`) VALUES ('2', 'feature', '1', '1', 'fa-hiking', NULL, NULL, NULL, NULL, '<strong>Somos un equipo apasionado de especialistas en viajes</strong> que brindamos experiencias de alto nivel en destinos emblemáticos como <strong>Machu Picchu, el Camino Inca, Salkantay</strong> y la majestuosa Montaña de Colores.', '<strong>We are a passionate team of travel specialists</strong> providing high-level experiences in iconic destinations such as <strong>Machu Picchu, the Inca Trail, Salkantay</strong>, and the majestic Rainbow Mountain.', '', '', '', '', '', '', '');
INSERT INTO `secciones_index` (`id`, `seccion`, `activo`, `orden`, `icono`, `titulo_es`, `titulo_en`, `subtitulo_es`, `subtitulo_en`, `texto_es`, `texto_en`, `boton_texto_es`, `boton_texto_en`, `boton_url`, `color_titulo`, `color_texto`, `tamano_titulo`, `tamano_texto`) VALUES ('3', 'feature', '1', '2', 'fa-user-check', NULL, NULL, NULL, NULL, '<strong>Sabemos que cada viajero es único</strong>, por eso diseñamos aventuras a tu medida, tomando el tiempo necesario para entender tus sueños y garantizando <strong>el viaje perfecto que recordarás toda la vida.</strong>', '<strong>We know that every traveler is unique</strong>, which is why we design tailor-made adventures, taking the necessary time to understand your dreams and guaranteeing <strong>the perfect trip you will remember for a lifetime.</strong>', '', '', '', '', '', '', '');
INSERT INTO `secciones_index` (`id`, `seccion`, `activo`, `orden`, `icono`, `titulo_es`, `titulo_en`, `subtitulo_es`, `subtitulo_en`, `texto_es`, `texto_en`, `boton_texto_es`, `boton_texto_en`, `boton_url`, `color_titulo`, `color_texto`, `tamano_titulo`, `tamano_texto`) VALUES ('4', 'feature', '1', '3', 'fa-users-cog', NULL, NULL, NULL, NULL, '<strong>Operamos con grupos pequeños y respeto total a la naturaleza</strong> para asegurar un servicio personalizado y de alta calidad. Nuestro lema es: <strong>\"Pequeños grupos, grandes aventuras\"</strong>.', '<strong>We operate with small groups and total respect for nature</strong> to ensure a personalized and high-quality service. Our motto is: <strong>\"Small groups, big adventures\"</strong>.', '', '', '', '', '', '', '');
INSERT INTO `secciones_index` (`id`, `seccion`, `activo`, `orden`, `icono`, `titulo_es`, `titulo_en`, `subtitulo_es`, `subtitulo_en`, `texto_es`, `texto_en`, `boton_texto_es`, `boton_texto_en`, `boton_url`, `color_titulo`, `color_texto`, `tamano_titulo`, `tamano_texto`) VALUES ('5', 'tours_header', '1', '0', '', 'Aventura, naturaleza y cultura en cada paso', 'Adventure, nature and culture at every step', 'Descubre la combinación perfecta entre aventura, cultura y naturaleza.', 'Discover the perfect combination of adventure, culture and nature.', 'Cada aventura está organizada por nuestro equipo de guías profesionales y certificados, comprometidos en hacer de tu viaje a <strong>Machu Picchu</strong> una experiencia inolvidable. Contamos con atención continua y servicios adaptados a cada viajero.', 'Each adventure is organized by our team of professional and certified guides, committed to making your trip to Machu Picchu an unforgettable experience. We offer continuous support and services tailored to each traveler.', '', '', '', '#33dbbf', '#000000', '', '');
INSERT INTO `secciones_index` (`id`, `seccion`, `activo`, `orden`, `icono`, `titulo_es`, `titulo_en`, `subtitulo_es`, `subtitulo_en`, `texto_es`, `texto_en`, `boton_texto_es`, `boton_texto_en`, `boton_url`, `color_titulo`, `color_texto`, `tamano_titulo`, `tamano_texto`) VALUES ('6', 'banner', '1', '0', ' fa-handshake', 'Tu seguridad y bienestar es nuestra prioridad', 'Your safety and well-being is our priority', 'Explora con confianza', 'Explore with confidence', 'La seguridad y tranquilidad de nuestros viajeros es una de nuestras principales prioridades. Por ello, trabajamos bajo estrictos estándares de calidad, salud y bienestar, garantizando experiencias seguras, organizadas y responsables en cada uno de nuestros tours. Nuestro compromiso también se extiende a las comunidades locales y al equipo humano que forma parte de cada aventura.', 'The safety and peace of mind of our travelers is one of our top priorities. Therefore, we operate under strict quality, health, and wellness standards, guaranteeing safe, organized, and responsible experiences on every tour. Our commitment also extends to the local communities and the team members who are part of each adventure.', 'Mayor Información', 'More Information', '#', '#000000', '#000000', '', '');
INSERT INTO `secciones_index` (`id`, `seccion`, `activo`, `orden`, `icono`, `titulo_es`, `titulo_en`, `subtitulo_es`, `subtitulo_en`, `texto_es`, `texto_en`, `boton_texto_es`, `boton_texto_en`, `boton_url`, `color_titulo`, `color_texto`, `tamano_titulo`, `tamano_texto`) VALUES ('7', 'destinos_header', '1', '0', 'fa-map-marked-alt', 'Destinos sugeridos en Perú', 'Suggested Destinations in Peru', 'Descubre Machu Picchu y Cusco junto a los mejores guías de viaje del país.', 'Discover Machu Picchu and Cusco with the best travel guides in the country.', 'Perú posee atracciones turísticas de clase mundial, imponentes sitios arqueológicos y una gran diversidad de flora y fauna. No importa qué tipo de viajero seas; el Perú te ofrece una amplia variedad de actividades para satisfacer todos los gustos.', 'Peru has world-class tourist attractions, imposing archaeological sites, and a great diversity of flora and fauna. No matter what type of traveler you are; Peru offers you a wide variety of activities to satisfy all tastes.', '', '', '', '', '', '', '');
INSERT INTO `secciones_index` (`id`, `seccion`, `activo`, `orden`, `icono`, `titulo_es`, `titulo_en`, `subtitulo_es`, `subtitulo_en`, `texto_es`, `texto_en`, `boton_texto_es`, `boton_texto_en`, `boton_url`, `color_titulo`, `color_texto`, `tamano_titulo`, `tamano_texto`) VALUES ('8', 'faq_header', '1', '0', 'fa-question-circle', 'Las preguntas más frecuentes', 'Frequently Asked Questions', 'Resolvemos tus dudas sobre IntiPath Tours', 'We solve your doubts about IntiPath Tours', NULL, NULL, '', '', '', '', '', '', '');
INSERT INTO `secciones_index` (`id`, `seccion`, `activo`, `orden`, `icono`, `titulo_es`, `titulo_en`, `subtitulo_es`, `subtitulo_en`, `texto_es`, `texto_en`, `boton_texto_es`, `boton_texto_en`, `boton_url`, `color_titulo`, `color_texto`, `tamano_titulo`, `tamano_texto`) VALUES ('9', 'licencias_header', '1', '0', '', 'Nuestras Licencias y Permisos', 'Our Licenses & Certifications', NULL, NULL, NULL, NULL, '', '', '', '', '', '', '');

