  `seccion2_titulo_en` varchar(255) DEFAULT 'Our Commitment',
  `cta_titulo` varchar(255) DEFAULT '¿Listo para tu próxima aventura?',
  `cta_titulo_en` varchar(255) DEFAULT 'Ready for your next adventure?',
  `cta_texto` text,
  `cta_texto_en` text,
