  `aside_texto_en` text,
  `aside_btn` varchar(100) DEFAULT NULL,
  `aside_btn_en` varchar(100) DEFAULT NULL,
  `aside_imagen` varchar(255) DEFAULT NULL,
  `aside_test_tit` varchar(255) DEFAULT NULL,
  `aside_test_tit_en` varchar(255) DEFAULT NULL,
  `aside_test_txt` text,
  `aside_test_txt_en` text,
  `aside_test_img` varchar(255) DEFAULT NULL,
  `aside_test_fecha` varchar(100) DEFAULT NULL,
  `aside_test_fecha_en` varchar(100) DEFAULT NULL,
  `banner_imagen` varchar(255) DEFAULT 'hero_tours.jpg',
  `titulo_general_card` varchar(255) DEFAULT NULL,
  `titulo_general_card_en` varchar(255) DEFAULT NULL,
  `banner_color_titulo` varchar(20) DEFAULT '#0f9b9e',
  `banner_color_subtitulo` varchar(20) DEFAULT '#f1f1f1',
  `intro_color_titulo` varchar(20) DEFAULT '#0f9b9e',
  `intro_color_texto` varchar(20) DEFAULT '#555555',
  `video_color_titulo` varchar(20) DEFAULT '#0f9b9e',
  `cards_color_titulo` varchar(20) DEFAULT '#0f9b9e',
  `cards_color_fondo` varchar(20) DEFAULT '#ffffff',
  `cards_color_check` varchar(20) DEFAULT '#c6d544',
  `aside_color_titulo` varchar(20) DEFAULT '#0f9b9e',
  `aside_color_btn` varchar(20) DEFAULT '#0f9b9e',
  `aside_color_btn_hover` varchar(20) DEFAULT '#c6d544',
  `cta_color_titulo` varchar(20) DEFAULT '#ffffff',
  `cta_color_texto` varchar(20) DEFAULT '#ffffff',
  `cta_color_btn` varchar(20) DEFAULT '#0f9b9e',
  `cta_color_btn_hover` varchar(20) DEFAULT '#c6d544',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

INSERT INTO `seguridad` (`id`, `banner_titulo`, `banner_subtitulo`, `banner_titulo_en`, `banner_subtitulo_en`, `intro_texto`, `intro_texto_en`, `video_url`, `seccion2_titulo`, `seccion2_titulo_en`, `cta_titulo`, `cta_titulo_en`, `cta_texto`, `cta_texto_en`, `cta_btn`, `cta_btn_en`, `cta_imagen`, `banner_titulo_size`, `banner_subtitulo_size`, `intro_titulo_size`, `aside_texto`, `aside_texto_en`, `aside_btn`, `aside_btn_en`, `aside_imagen`, `aside_test_tit`, `aside_test_tit_en`, `aside_test_txt`, `aside_test_txt_en`, `aside_test_img`, `aside_test_fecha`, `aside_test_fecha_en`, `banner_imagen`, `titulo_general_card`, `titulo_general_card_en`, `banner_color_titulo`, `banner_color_subtitulo`, `intro_color_titulo`, `intro_color_texto`, `video_color_titulo`, `cards_color_titulo`, `cards_color_fondo`, `cards_color_check`, `aside_color_titulo`, `aside_color_btn`, `aside_color_btn_hover`, `cta_color_titulo`, `cta_color_texto`, `cta_color_btn`, `cta_color_btn_hover`) VALUES ('1', 'Seguridad en tus Viajes', 'Viaja con total tranquilidad y vive experiencias inolvidables con asistencia las 24 horas.', 'Safety in your Travels', 'Travel with complete peace of mind and live unforgettable experiences with 24/7 assistance.', 'La seguridad y el bienestar de nuestros viajeros son una prioridad en cada una de nuestras experiencias. En IntiPath Tours, trabajamos con altos estándares de calidad para garantizar que puedas disfrutar de cada aventura con tranquilidad, confianza y el respaldo de un equipo profesional.\r\n\r\n✅Protocolos de bioseguridad y asistencia médica integral durante toda tu ruta.\r\n✅Guías certificados y expertos locales con amplia experiencia en destinos turísticos, trekking y actividades de aventura.\r\n✅Comunicación permanente mediante equipos de radio y sistemas de coordinación en rutas de difícil acceso.\r\n✅Seguro de viaje con cobertura para actividades de aventura y trekking según el servicio contratado.\r\n✅Transporte turístico seguro, cómodo y operado por conductores profesionales.\r\n✅Monitoreo constante de las condiciones climáticas y del estado de las rutas para garantizar recorridos seguros.\r\n✅Orientación y recomendaciones antes de cada actividad para una mejor preparación física y logística.\r\n✅Asistencia personalizada antes, durante y después de cada tour.\r\n\r\n- En IntiPath Tours nos aseguramos de que cada detalle de tu viaje esté respaldado por los más altos estándares de seguridad, planificación y atención al cliente. Nuestro compromiso es brindarte experiencias inolvidables mientras exploras los destinos más impresionantes del Perú con la confianza de estar acompañado por profesionales que velan por tu bienestar en todo momento. Tu única preocupación será disfrutar del camino, los paisajes y cada momento de la aventura.', 'The safety and well-being of our travelers are a priority in every one of our experiences. At IntiPath Tours, we work with high standards of quality to ensure you can enjoy each adventure with peace of mind, confidence, and the support of a professional team.\r\n\r\n✅ Biosecurity protocols and comprehensive medical assistance throughout your trip.\r\n\r\n✅ Certified guides and local experts with extensive experience in tourist destinations, trekking, and adventure activities.\r\n✅ Constant communication via radio equipment and coordination systems on difficult-to-access routes.\r\n✅ Travel insurance with coverage for adventure and trekking activities, depending on the service booked.\r\n✅ Safe and comfortable tourist transportation operated by professional drivers.\r\n✅ Constant monitoring of weather conditions and road conditions to guarantee safe journeys.\r\n✅ Guidance and recommendations before each activity for better physical and logistical preparation.\r\n✅ Personalized assistance before, during, and after each tour.\r\n\r\nAt IntiPath Tours, we ensure that every detail of your trip is backed by the highest standards of safety, planning, and customer service. Our commitment is to provide you with unforgettable experiences as you explore Peru\'s most breathtaking destinations, with the confidence of being accompanied by professionals who look after your well-being at all times. Your only concern will be enjoying the journey, the scenery, and every moment of the adventure.', 'https://www.tiktok.com/@inti.path.tours/video/7632103102325230855', 'Nuestro Compromiso', 'Our Commitment', '¿Listo para tu próxima aventura?', 'Ready for your next adventure?', 'No dejes para mañana los paisajes que puedes descubrir hoy. Explora nuestras rutas exclusivas, planifica tu viaje a medida con nuestros expertos locales y asegura una experiencia inolvidable y segura en Cusco. ¡El viaje de tus sueños está a solo un clic de distancia!', 'Don\'t leave for tomorrow the landscapes you can discover today. Explore our exclusive routes, plan your tailor-made trip with our local experts, and ensure a safe, unforgettable experience in Cusco. Your dream journey is just a click away!', 'Contáctanos', 'Contact Us', 'seg_cta_1778993118.jpg', '64', '24', '40', '¿Tienes dudas sobre tu próxima aventura? Nuestro especialista en rutas y seguridad te asesora de forma personalizada para que elijas el viaje perfecto.', 'Have questions about your next adventure? Our route and safety specialist provides personalized advice to help you choose the perfect trip.', 'Hablar con un Experto', 'Talk to an Expert', 'seg_spec_1780589910.jpg', 'Una experiencia inolvidable y segura', 'An unforgettable and safe experience', '\"Viajar con ellos fue la mejor decisión. El equipo estuvo pendiente de nosotros en cada tramo del camino, los guías demostraron un conocimiento increíble y nos sentimos totalmente protegidos. ¡Altamente recomendados!\"', '\"Traveling with them was the best decision. The team watched over us every step of the way, the guides showed incredible knowledge, and we felt completely safe. Highly recommended!\"', 'seg_testimonio_1780589910.jpg', 'Mayo 2026', 'May 2026', 'seg_banner_1786201532.jpg', 'Nuestro equipo de emergencia', 'Our emergency team', '#ffffff', '#f1f1f1', '#0f9b9e', '#555555', '#0f9b9e', '#0f9b9e', '#ffffff', '#c6d544', '#0f9b9e', '#0f9b9e', '#c6d544', '#ffffff', '#ffffff', '#0f9b9e', '#c6d544');

DROP TABLE IF EXISTS `seguridad_cards`;
CREATE TABLE `seguridad_cards` (
  `id` int NOT NULL AUTO_INCREMENT,
  `imagen` varchar(255) DEFAULT NULL,
  `titulo` varchar(255) DEFAULT NULL,
  `titulo_en` varchar(255) DEFAULT NULL,
  `descripcion` text,
  `descripcion_en` text,
  `orden` int DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

