  `banner_subtitulo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `banner_subtitulo_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `intro_texto` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `intro_texto_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `intro_imagen` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `aside_texto` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `aside_texto_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
