  `aside_imagen` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `cta_titulo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `cta_titulo_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `cta_texto` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `cta_texto_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `cta_btn` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `cta_btn_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `cta_imagen` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `aside_test_tit` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `aside_test_tit_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `aside_test_txt` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `aside_test_txt_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `aside_test_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `aside_test_fecha` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `aside_test_fecha_en` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `color_titulo` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `tamano_titulo` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `color_texto` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `tamano_texto` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `seguridad_viaje` (`id`, `banner_titulo`, `banner_titulo_en`, `banner_subtitulo`, `banner_subtitulo_en`, `intro_texto`, `intro_texto_en`, `intro_imagen`, `aside_texto`, `aside_texto_en`, `aside_btn`, `aside_btn_en`, `aside_imagen`, `cta_titulo`, `cta_titulo_en`, `cta_texto`, `cta_texto_en`, `cta_btn`, `cta_btn_en`, `cta_imagen`, `aside_test_tit`, `aside_test_tit_en`, `aside_test_txt`, `aside_test_txt_en`, `aside_test_img`, `aside_test_fecha`, `aside_test_fecha_en`, `color_titulo`, `tamano_titulo`, `color_texto`, `tamano_texto`) VALUES ('1', 'Seguridad en tu Viaje', 'Travel Safety', 'Consejos para una aventura segura en Perú', 'Tips for a safe adventure in Peru', 'Perú es un destino seguro para turistas, pero como en cualquier viaje, es importante estar bien informado antes de emprender una nueva aventura. Conocer aspectos relacionados con la documentación necesaria, recomendaciones de salud, formas de pago y algunas medidas básicas de seguridad te permitirá disfrutar de cada experiencia con mayor tranquilidad y confianza.\r\n\r\nEn IntiPath Tours nos preocupamos por brindarte una experiencia segura, organizada y memorable, acompañándote en cada paso de tu viaje para que solo te preocupes por disfrutar de los increíbles paisajes, la cultura y la historia que hacen único al Perú.\r\n', 'Peru is a safe destination for tourists, but as with any trip, it\'s important to be well-informed before embarking on a new adventure. Knowing about the necessary documentation, health recommendations, payment methods, and some basic safety measures will allow you to enjoy each experience with greater peace of mind and confidence.\r\n\r\nAt IntiPath Tours, we are committed to providing you with a safe, organized, and memorable experience, accompanying you every step of the way so you can focus solely on enjoying the incredible landscapes, culture, and history that make Peru unique.', 'seguridad_banner_1780589487.jpg', 'Estamos listos para ayudarte a planificar la mejor experiencia de viaje. Si tienes consultas sobre nuestros tours, itinerarios, horarios o reservas, no dudes en contactarnos.\r\n\r\n📩 Déjanos tu mensaje y uno de nuestros expertos en viajes se comunicará contigo a la brevedad para brindarte asesoramiento personalizado y toda la información que necesitas.\r\n\r\n🌎 Tu próxima aventura comienza aquí. ¡Estamos para ayudarte!', 'We\'re ready to help you plan the best travel experience. If you have any questions about our tours, itineraries, schedules, or reservations, please don\'t hesitate to contact us.\r\n\r\n📩 Leave us a message, and one of our travel experts will get in touch with you shortly to provide personalized advice and all the information you need.\r\n\r\n🌎 Your next adventure starts here. We\'re here to help!', 'Contacto de Emergencia', 'Emergency Contact', 'seguridad_spec_1780589140.jpg', 'Viaja con confianza', 'Travel with confidence', 'Tu seguridad es nuestra prioridad número uno', 'Your safety is our number one priority', 'Conoce Más', 'Learn More', 'seguridad_cta_bg_1780589379.jpg', '', '', NULL, NULL, '', '', '', '#e8ac18', '3rem', '#333333', '1.1rem');

DROP TABLE IF EXISTS `sliders`;
CREATE TABLE `sliders` (
  `id` int NOT NULL AUTO_INCREMENT,
  `imagen` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `titulo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `titulo_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `subtitulo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `subtitulo_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `orden` int DEFAULT '0',
  `fecha_registro` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO `sliders` (`id`, `imagen`, `titulo`, `titulo_en`, `subtitulo`, `subtitulo_en`, `orden`, `fecha_registro`) VALUES ('7', 'video_slider_1781706200.mp4', 'DESCUBRE LA CULTURA, LA NATURALEZA  Y LA MÁGIA ANDINA', 'DISCOVER ANDEAN CULTURE, NATURE AND MAGIC', '', '', '0', '2026-04-14 10:45:06');

DROP TABLE IF EXISTS `terminos_condiciones`;
CREATE TABLE `terminos_condiciones` (
  `id` int NOT NULL AUTO_INCREMENT,
  `contenido` text,
  `ultima_actualizacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

INSERT INTO `terminos_condiciones` (`id`, `contenido`, `ultima_actualizacion`) VALUES ('1', '# TÉRMINOS Y CONDICIONES DE RESERVA\r\n## INTI PATH TOURS: Donde comienza tu verdadera aventura\r\nElegir Inti Path Tours no es solo reservar un viaje… es confiar en un equipo que vive cada ruta\r\ncon pasión y convierte cada experiencia en algo verdaderamente inolvidable.\r\nPara nosotros, es un honor acompañarte en momentos que no solo se disfrutan, sino que se\r\nquedan contigo para siempre.\r\nNuestra misión es clara: transformar tus vacaciones en una aventura única, llena de emociones,\r\ndescubrimientos y recuerdos que marcarán tu historia. Cada detalle ha sido cuidadosamente\r\ndiseñado para llevarte más allá de lo esperado.\r\nCon el objetivo de brindarte un viaje seguro, organizado y sin preocupaciones, te invitamos a\r\nrevisar nuestros términos y condiciones. Tu conocimiento y compromiso son clave para que\r\ntodo fluya perfectamente y tú solo te concentres en disfrutar.\r\nAquí no solo creamos itinerarios… creamos experiencias que despiertan tu espíritu aventurero.\r\n                 Explora, siente y vive una experiencia que marcará tu historia.\r\n## Aceptación de nuestros términos y condiciones\r\nAl realizar una reserva con nosotros —ya sea por web, correo, redes sociales o de manera\r\npresencial— confirmas automáticamente la aceptación de nuestros términos y condiciones.\r\nEste acuerdo ha sido diseñado para garantizarte una experiencia transparente, segura y de alta\r\ncalidad desde el primer momento.\r\n## Actualización de nuestros términos\r\nEn Inti Path Tours creemos en mejorar constantemente para ofrecerte experiencias cada vez\r\nmás completas. Por ello, nos reservamos el derecho de actualizar nuestros términos y\r\ncondiciones en cualquier momento.\r\nTe recomendamos revisarlos periódicamente, para que siempre viajes con total confianza y\r\ntranquilidad.\r\nCada mejora está pensada para seguir creando viajes extraordinarios para ti.\r\n## Confirmación de tu reserva\r\nUna vez enviada tu solicitud, esta quedará sujeta a la validación del pago correspondiente.\r\nPosteriormente, recibirás un documento detallado con toda la información de tu experiencia,\r\nincluyendo servicios incluidos y no incluidos.\r\nSi no recibimos observaciones tras nuestra comunicación, se entenderá que aceptas plenamente\r\nlas condiciones establecidas.\r\n## Importante:\r\n- Te recomendamos leer detenidamente nuestros términos antes de confirmar tu reserva.\r\nNuestro compromiso es que vivas una experiencia clara, organizada y completamente libre de\r\ncontratiempos.\r\n# 1. RESERVAS\r\nEl momento de vivir una experiencia única ha llegado. Reservar con nosotros es fácil, rápido y\r\ntotalmente seguro. Estamos listos para acompañarte desde el primer paso:\r\n- WhatsApp: 920 307 331\r\n- Correo: intipathtourstrekkinperu@gmail.com\r\nSi decides reservar a través de nuestra web, solo asegúrate de completar tus datos\r\ncorrectamente. Es muy importante que tu nombre y número de pasaporte coincidan\r\nexactamente con tu documento oficial, y que tu información de contacto esté actualizada para\r\nmantenerte siempre informado.\r\n## Nosotros nos encargamos de todo:\r\n- Una vez realizado tu pago, nuestro equipo se ocupa de verificar disponibilidad, gestionar\r\npermisos y coordinar cada detalle… para que tú solo te dediques a disfrutar la experiencia.\r\n## Confirmación de tu aventura:\r\n- Tu reserva quedará 100% confirmada cuando recibas nuestra validación oficial por correo\r\nelectrónico. Ese será el inicio real de tu próxima gran historia.\r\n# 2. POLÍTICAS DE RESERVA – INTI PATH TOURS TREKKING PERÚ\r\n## 2.1. Depósito inicial – Tu aventura comienza aquí\r\nEl primer paso hacia una experiencia inolvidable está a solo un clic. Para asegurar tu lugar en\r\ncualquiera de nuestros tours, solo necesitas realizar un depósito inicial no reembolsable, el cual\r\nvaría según la aventura que elijas.\r\nPuedes hacerlo de forma rápida, segura y sin complicaciones a través de:\r\n- Tarjeta de crédito o débito (comisión del 5%)\r\n- PayPal (comisión del 8%)\r\nAl confirmar tu reserva, no solo garantizas tu espacio… das el primer paso hacia paisajes únicos,\r\ncultura viva y momentos que recordarás toda la vida y aceptas los Términos y Condiciones de\r\nnuestros servicios.\r\n## Confirmación de tu reserva:\r\n- Tu aventura se vuelve oficial una vez que recibimos tu información completa y verificamos el\r\ndepósito. Desde ese instante, comenzamos a planificar cada detalle de tu viaje para que vivas\r\nuna experiencia perfectamente organizada e inolvidable.\r\n## Compromiso del grupo:\r\n- La persona que realiza la reserva representa a todos los viajeros incluidos, confirmando que cada\r\nintegrante ha sido informado y acepta nuestros Términos y Condiciones. Así garantizamos una\r\nexperiencia clara, organizada y sin sorpresas.\r\n## Información necesaria para tu viaje:\r\nPara brindarte una experiencia segura y sin contratiempos, necesitaremos:\r\n- Nombre completo\r\n- Número de pasaporte o documento de identidad\r\n- Género\r\n- Nacionalidad\r\n- Fecha de nacimiento\r\nEstos datos son esenciales para gestionar permisos, accesos y toda la logística de tu aventura.\r\n## Depósitos según el tipo de experiencia\r\nEl monto del depósito inicial dependerá del itinerario elegido, ya sea una caminata de varios\r\ndías, una ruta alternativa o una experiencia más corta.\r\n- Importante: Te recomendamos revisar esta información antes de reservar. En Inti Path Tours,\r\ntrabajamos con total transparencia para que tu única preocupación sea disfrutar el viaje.\r\n# 3. POLÍTICAS DE PAGO\r\nEn Inti Path Tours, cuidamos cada detalle desde el primer momento para que tú solo te concentres en lo más importante: vivir una experiencia inolvidable.\r\n## Métodos de pago:\r\nElige la opción que mejor se adapte a ti:\r\n- Efectivo\r\n- Tarjetas de crédito o débito\r\n- PayPal\r\n- Importante:\r\nPara garantizar una organización impecable, el pago total del tour debe estar completado antes\r\ndel inicio del recorrido. Así aseguramos que todo esté listo para tu gran aventura.\r\n## Pago final:\r\nEl saldo restante debe cancelarse hasta 48 horas antes del inicio de la excursión mediante:\r\n- Efectivo.\r\n- PayPal (8% de comisión).\r\n- Tarjeta de crédito o débito (5% de comisión).\r\n## Pagos en efectivo:\r\nSi prefieres esta opción, te recomendamos realizar el pago con al menos 48 horas de anticipación.\r\n- Aceptamos:\r\n- Dólares estadounidenses\r\n- Soles peruanos (según tipo de cambio del día en oficina)\r\n- Nota: Para un proceso ágil y sin inconvenientes, recibimos únicamente billetes en buen\r\nestado.\r\n## Comisiones bancarias:\r\nLos costos adicionales generados por transacciones serán asumidos por el cliente.\r\n## Depósito inicial:\r\n- El depósito no es reembolsable ni transferible, ya que se utiliza de forma inmediata para\r\nasegurar accesos, permisos, reservas de hoteles, trenes y servicios especializados que harán\r\nposible tu experiencia.\r\n## Estamos contigo en cada paso:\r\n- Si tienes alguna duda, tu asesor de aventuras estará listo para acompañarte y brindarte la mejor\r\natención en todo momento.\r\n## Antes de reservar:\r\n- Te invitamos a revisar nuestras políticas. Nosotros nos encargamos de cada detalle… tú solo\r\nprepárate para descubrir, explorar y vivir una experiencia única.\r\n# 4. CAMBIOS DE FECHA\r\nEn Inti Path Tours entendemos que cada viaje es único, y aunque el destino sigue siendo el mismo, estamos aquí para ayudarte a reprogramar tu experiencia y mantener viva la emoción de tu próxima gran aventura.\r\n## Reprograma tu experiencia:\r\n- Puedes solicitar el cambio de fecha de tu tour con una tarifa desde US$200 por persona,\r\ndependiendo del paquete seleccionado.\r\n## ¿A qué corresponde este importe?\r\n- Más que un costo, es la gestión necesaria para asegurar nuevamente tu ingreso. Las entradas y\r\nservicios turísticos en destinos como Machu Picchu son altamente exclusivos y se adquieren con\r\nanticipación, siendo no reembolsables ni transferibles. Por ello, es necesario gestionar nuevos\r\naccesos para tu nueva fecha.\r\n## Experiencias adicionales:\r\n- Si tu viaje incluye accesos especiales o mejoras como: Huayna Picchu, Montaña Machu Picchu u otros personalizados.\r\n- Estos estarán sujetos a disponibilidad y a cargos adicionales, ya que forman parte de experiencias exclusivas de alta demanda.\r\n## A tener en cuenta:\r\n- Los ingresos a Machu Picchu y atractivos complementarios son limitados y muy solicitados, por\r\nlo que no admiten cambios ni devoluciones. Elegir bien tu fecha es clave para vivir tu experiencia\r\nsin interrupciones.\r\n\r\nEn Inti Path Tours, transformamos los imprevistos en nuevas oportunidades para viajar. Nuestro\r\ncompromiso es acompañarte en cada paso, con transparencia, organización y la pasión de crear\r\nexperiencias que realmente se viven… y nunca se olvidan.\r\n# 5. POLÍTICAS DE CANCELACIÓN\r\nTu aventura es un sueño… y queremos ayudarte a cuidarlo desde el inicio.\r\n\r\nEn Inti Path Tours, cada experiencia se planifica con dedicación, anticipación y acceso a servicios\r\nexclusivos. Por eso, te compartimos nuestras políticas de cancelación con total transparencia,\r\npara que tomes decisiones seguras y sin sorpresas.\r\n## ¿Necesitas cancelar tu viaje?\r\nPuedes hacerlo comunicándote por correo electrónico con tu Asesor de Aventuras. La solicitud\r\ndebe ser realizada por la persona que confirmó la reserva.\r\nDebido a la alta demanda y a la gestión anticipada de ingresos, permisos y servicios, las reservas\r\nconfirmadas no son reembolsables. Por ello, te recomendamos elegir tus fechas con seguridad\r\nantes de dar este gran paso.\r\n## Cargos por cancelación:\r\nAl tratarse de experiencias cuidadosamente organizadas, aplican las siguientes condiciones:\r\n- Más de 42 días de anticipación: 60% del costo total.\r\n- Hasta 14 días de anticipación: 80% del costo total.\r\n- Dentro de los 7 días previos al viaje: 100% del costo total.\r\n## Una vez iniciada la experiencia:\r\nLa aventura no se detiene… pero si decides interrumpirla o no puedes continuar:\r\n- No se realizan reembolsos.\r\n- Los gastos adicionales serán asumidos por el viajero.\r\n- Podrás integrarte a la visita final a Machu Picchu (previa coordinación).\r\n## Cuando la naturaleza decide:\r\nEn destinos como los Andes, la seguridad siempre es primero. Ante desastres naturales o\r\nsituaciones fuera de nuestro control:\r\n- Podremos ajustar el itinerario para proteger tu bienestar.\r\n- No se aplican reembolsos en estos casos.\r\n## Eventos globales o imprevistos mayores:\r\nSi una situación externa impide tu experiencia:\r\n- No se realizan reembolsos.\r\n- Te brindaremos la opción de reprogramar tu viaje para que no pierdas la oportunidad de vivirlo.\r\n## Sobre tu participación:\r\n- No asistir a reuniones informativas o actividades será considerado como inasistencia.\r\n- Los servicios no utilizados no son reembolsables.\r\n## Nuestro compromiso:\r\n- Cada reserva activa un proceso inmediato de planificación, coordinación y aseguramiento de\r\nespacios únicos. Por eso, estas políticas nos permiten garantizarte una experiencia de alto nivel,\r\norganizada al detalle.\r\nTú eliges el momento… nosotros nos encargamos de hacerlo inolvidable.\r\n# 6. POLÍTICAS DE LA EXCURSIÓN POR EL CAMINO INCA:\r\nReservar esta aventura es asegurar tu lugar en una de las caminatas más icónicas del mundo.\r\nPara que todo fluya perfectamente, es importante conocer cómo funcionan los permisos y\r\nbeneficios asociados a esta experiencia exclusiva.\r\n## Permiso oficial para el Camino Inca:\r\nAl confirmar tu reserva, obtienes un permiso único y personal que te permitirá recorrer esta\r\nlegendaria ruta hacia Machu Picchu. Este acceso es limitado y altamente solicitado, por lo que\r\nconsidera lo siguiente:\r\n- Personal e intransferible: Tu permiso está emitido exclusivamente a tu nombre y no\r\npuede ser cedido a otra persona.\r\n- No reembolsable: Una vez adquirido, el permiso no admite devoluciones bajo ninguna\r\ncircunstancia.\r\n- Fechas fijas: No es posible modificar la fecha del permiso después de su emisión.\r\n- Regulación oficial: Estas condiciones son establecidas por el Gobierno peruano, lo que\r\ngarantiza el cuidado, control y preservación de esta maravilla histórica.\r\n## ¿Y si ocurre algo inesperado?\r\nSi por causas externas, como condiciones climáticas o disposiciones oficiales, el Camino Inca se\r\ncierra temporalmente, en Inti Path Tours nos encargamos de que tu experiencia continúe. Te\r\nofreceremos una ruta alternativa cuidadosamente diseñada para que sigas viviendo una\r\naventura inolvidable.\r\n## Beneficio para jóvenes viajeros:\r\n- Descuento especial: US$20.00\r\n- Aplica para: Viajeros de 17 años o menos.\r\n- Requisito: Presentar copia de pasaporte vigente al momento de la reserva.\r\nNosotros nos encargamos de cada detalle para que tú solo te conectes con la historia, la\r\nnaturaleza y la magia de los Andes.\r\n# 7. TÉRMINOS Y CONDICIONES DE LA EXCURSIÓN - INTI PATH TOURS\r\nEn Inti Path Tours, cada detalle está diseñado para que vivas una travesía única, segura y perfectamente organizada. A continuación, te compartimos las condiciones que hacen posible esta experiencia inolvidable:\r\n## Precios y acomodación:\r\nNuestros precios están pensados por persona, en base a ocupación doble en hoteles, campamentos o tiendas.\r\nSi viajas solo, podrás compartir con otro viajero del mismo sexo o elegir mayor privacidad con un costo adicional.\r\n## Pagos y organización:\r\nPara asegurar que todo esté listo para tu aventura, el saldo restante debe completarse hasta 48\r\nhoras antes del inicio del tour.\r\n- Nota: Pagos con tarjeta (5%) y PayPal (8%) incluyen comisiones por procesamiento.\r\n## Experiencia en grupo:\r\n- Viajar en grupo es compartir, descubrir y conectar. Ten en cuenta que el ritmo puede variar\r\nsegún el grupo, siempre priorizando una experiencia equilibrada y segura. Si en algún momento\r\ndeseas apoyo o asistencia, nuestro equipo estará contigo en todo momento.\r\n## Transporte e itinerario:\r\nIncluimos transporte de ida y retorno a Cusco, con servicios coordinados para tu comodidad.\r\nPara garantizar tu seguridad y la mejor experiencia, el itinerario puede adaptarse ante cualquier\r\ncircunstancia necesaria.\r\n## Tu bienestar es nuestra prioridad:\r\nNuestro equipo está preparado para asistirte en todo momento. En caso de malestar o dificultad\r\ndurante la ruta:\r\n- Te acompañaremos hasta recibir atención adecuada.\r\n- Te ayudaremos a continuar o reencontrarte con el grupo cuando sea posible.\r\n- Los gastos médicos o evacuaciones especiales serán asumidos por el viajero.\r\nRecomendación: Contar con un seguro de viaje te brindará mayor tranquilidad durante toda tu experiencia.\r\n## Compromiso y responsabilidad:\r\nTrabajamos con profesionales altamente capacitados para brindarte seguridad y confianza en cada paso.\r\nSin embargo:\r\n- Cada viajero es responsable de sus pertenencias personales.\r\n- No podemos asumir responsabilidad por factores externos como clima, desastres naturales, huelgas u otros imprevistos.\r\n## Documentación de viaje:\r\n- Asegúrate de viajar con un pasaporte vigente (mínimo 6 meses de validez).\r\n- Si realizas cambios en tu documento, es importante informarnos de inmediato para\r\nevitar inconvenientes en tu ingreso a destinos como Machu Picchu.\r\n## Grupos e idiomas:\r\n- Nuestras experiencias se realizan principalmente en español e inglés, en grupos reducidos (hasta 12 personas), creando un ambiente más cercano, seguro y enriquecedor.\r\nNosotros nos encargamos de la logística… tú solo déjate llevar por la magia del camino.\r\n# 8. TÉRMINOS DE ALOJAMIENTO Y CONDICIONES ADICIONALES:\r\nDescansa, recarga energías y vive cada momento al máximo.\r\n- En Inti Path Tours, cuidamos cada detalle para que tu experiencia no solo sea una aventura, sino\r\ntambién un espacio de confort, seguridad y tranquilidad durante todo tu viaje.\r\n## Alojamiento pensado para ti:\r\nQueremos que te sientas cómodo en cada etapa de tu experiencia:\r\n- Habitaciones dobles: Espacios acogedores con dos camas individuales y servicios\r\nprivados, ideales para descansar después de cada jornada.\r\n- Habitaciones matrimoniales: Si prefieres mayor privacidad, podemos gestionar una\r\nhabitación con cama doble. Solo indícalo al momento de tu reserva.\r\n- Mejoras y solicitudes especiales: ¿Quieres elevar tu experiencia? Contamos con\r\nopciones de upgrade y noches adicionales. Avísanos con anticipación y nos encargamos\r\nde todo.\r\n- Viajeros individuales: Si viajas solo, compartirás habitación con otro viajero del mismo\r\nsexo. También puedes optar por una habitación privada con un costo adicional.\r\nNuestro compromiso es ofrecerte un ambiente cálido, cómodo y adaptado a tus necesidades.\r\n## Sobre la experiencia de aventura:\r\nExplorar los Andes es una vivencia única… y como toda gran aventura, implica contacto con la\r\nnaturaleza en su estado más puro. Factores como el clima, la geografía o el entorno forman\r\nparte de esta experiencia. Al viajar con nosotros, aceptas vivir esta conexión auténtica con el\r\ndestino.\r\n## Responsabilidad y compromiso:\r\nTrabajamos con altos estándares para brindarte seguridad y confianza en cada paso. Sin embargo:\r\n- Nuestra responsabilidad se limita al valor total del servicio contratado.\r\n- No asumimos responsabilidad por pérdidas, daños o gastos derivados de situaciones\r\nexternas o imprevistas.\r\n## Marco legal:\r\n- Todas nuestras operaciones se rigen bajo la legislación peruana. Al confirmar tu reserva, aceptas\r\nque cualquier gestión o eventualidad se resolverá conforme a las leyes y tribunales del Perú.\r\nViajar con nosotros es más que recorrer un destino… es sentirte cuidado en cada detalle.\r\n# 9. INFORMACIÓN MÉDICA Y RESPONSABILIDADES:\r\nTu bienestar es el corazón de cada aventura.\r\n- En Inti Path Tours, tu seguridad no es un detalle… es nuestra prioridad absoluta. Queremos que\r\nvivas una experiencia inolvidable en los Andes, con la tranquilidad de estar bien preparado en\r\ncada paso.\r\n## Información de salud – clave para tu experiencia:\r\n- Al momento de tu reserva, es fundamental que nos informes sobre cualquier condición médica, alergia o situación de salud relevante. Esta información nos permite acompañarte mejor y brindarte una experiencia segura y adaptada \r\na ti.\r\n## Condición física y preparación:\r\nNuestras experiencias requieren un buen estado físico para que puedas disfrutarlas al máximo:\r\n- Los participantes deben encontrarse en condiciones adecuadas para realizar la\r\nexcursión.\r\n- Mayores de 70 años deberán presentar un certificado médico que confirme que puede\r\nrealizar el tour de su preferencia.\r\n- Si tienes alguna condición médica, será necesario un certificado actualizado que\r\nautorice tu participación.\r\nImportante: No informar o no presentar la documentación requerida puede limitar tu participación, ya que tu seguridad es lo primero.\r\n## Evalúa tu aventura con responsabilidad:\r\nCada viajero es único. Por eso, te recomendamos:\r\n- Evaluar tu estado físico y salud antes de viajar.\r\n- Consultar con tu médico sobre tu estado de salud, vacunas y medidas preventivas.\r\nNosotros organizamos tu experiencia… pero tu bienestar empieza contigo.\r\n## Participación segura:\r\n- Para cuidar de todo el grupo, nos reservamos el derecho de restringir la participación si consideramos que existe algún riesgo para ti o para otros viajeros.\r\n## Viajar durante el embarazo:\r\n- El embarazo también debe ser informado al momento de la reserva y contar con autorización médica. Esto nos permite garantizar una experiencia segura para ti y tu acompañante.\r\n## Seguro de viaje – tu mejor aliado:\r\nTe recomendamos contar con un seguro de viaje completo que te respalde ante cualquier\r\neventualidad, como:\r\n- Emergencias médicas\r\n- Cancelaciones\r\n- Situaciones imprevistas\r\n## Nuestro compromiso contigo:\r\n- En Inti Path Tours, cuidamos cada detalle para que vivas una experiencia segura, consciente y\r\nrealmente inolvidable. Tu transparencia y preparación son clave para que todo fluya… y tú solo\r\nte enfoques en disfrutar el camino.\r\n# 10. PROTECCIÓN DE DATOS:\r\n- En Inti Path Tours, tu confianza es tan importante como tu experiencia. Por ello, protegemos tu información personal con los más altos estándares de seguridad, en cumplimiento de la Ley N.° 29733 – Ley de Protección de Datos Personales del Perú.\r\nToda la información que nos brindas es almacenada de forma segura y confidencial, y será\r\nutilizada únicamente para:\r\n- Gestionar tus reservas y solicitudes.\r\n- Brindarte información sobre nuestros servicios.\r\n- Mantenerte al tanto de novedades y experiencias que puedan interesarte.\r\n## Uso responsable de tu información:\r\n- Para acceder a ciertos servicios, es posible que necesitemos algunos datos personales. Ten la\r\ntranquilidad de que estos serán utilizados exclusivamente para el propósito específico para el\r\ncual fueron recopilados.\r\n## Los datos solicitados pueden incluir:\r\n- Nombre completo, correo electrónico, fecha de nacimiento, género, país y ciudad de origen,\r\nentre otros. Solo requerimos la información estrictamente necesaria para ofrecerte un servicio\r\neficiente y personalizado.\r\n## Tu información está protegida:\r\nNo compartimos ni divulgamos tus datos personales con terceros, salvo en los siguientes casos:\r\n- Cuando cuentes con tu autorización expresa\r\n- Cuando sea requerido por una autoridad competente conforme a la ley\r\n- Cuando sea necesario para cumplir nuestros términos, proteger a otros usuarios o resguardar la integridad \r\nde nuestros servicios.\r\nTu seguridad y privacidad son parte esencial de la experiencia que te ofrecemos.\r\n', '2026-04-20 12:09:23');

DROP TABLE IF EXISTS `tipos_tours`;
CREATE TABLE `tipos_tours` (
  `id` int NOT NULL AUTO_INCREMENT,
  `tours_id` int NOT NULL,
  `nombre` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `slug` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `meta_titulo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `meta_descripcion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  PRIMARY KEY (`id`),
  KEY `fk_tipos_tours_relacion` (`tours_id`),
  CONSTRAINT `fk_tipos_tours_relacion` FOREIGN KEY (`tours_id`) REFERENCES `tours` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `tipos_tours_ibfk_1` FOREIGN KEY (`tours_id`) REFERENCES `tours` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

DROP TABLE IF EXISTS `tours`;
CREATE TABLE `tours` (
  `id` int NOT NULL AUTO_INCREMENT,
  `titulo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `titulo_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `destacados` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `destacados_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `slug` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `descripcion_corta` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `descripcion_corta_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `titulo_corto` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `titulo_corto_en` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `descripcion_detallada` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `descripcion_detallada_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `itinerario` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
