INSERT INTO `tours` (`id`, `titulo`, `titulo_en`, `destacados`, `destacados_en`, `slug`, `descripcion_corta`, `descripcion_corta_en`, `titulo_corto`, `titulo_corto_en`, `descripcion_detallada`, `descripcion_detallada_en`, `itinerario`, `itinerario_en`, `itinerario_resumen`, `itinerario_resumen_en`, `info_importante`, `info_importante_en`, `incluye`, `incluye_en`, `no_incluye`, `no_incluye_en`, `extras_texto`, `extras_texto_en`, `aclimatacion_texto`, `aclimatacion_texto_en`, `lista_equipaje`, `lista_equipaje_en`, `precio`, `porcentaje_adelanto`, `max_personas`, `precio_grupal`, `pago_adelantado`, `saldo_cusco`, `tipo_precio`, `duracion`, `duracion_en`, `imagen_principal`, `estado`, `en_menu`, `fecha_creacion`, `mostrar_precio`, `moneda`, `es_recomendado`, `en_oferta`, `id_categoria`, `video_url`, `altitud_max`, `dificultad`, `ubicacion_texto`, `distancia_caminata`, `comidas_info`, `comidas_info_en`, `folleto_pdf`, `mapa_imagen`, `img_galeria1`, `img_galeria2`, `img_galeria3`, `img_galeria4`, `info_importante_detallada`, `info_importante_detallada_en`, `pq_titulo1`, `pq_desc1`, `pq_img1`, `pq_titulo2`, `pq_desc2`, `pq_img2`, `pq_titulo3`, `pq_desc3`, `pq_img3`, `antes_de_viajar`, `antes_de_viajar_en`, `galeria_itinerario`, `parent_id`, `precio_nino`) VALUES ('33', ' AUSANGATE', 'AUSANGATE', 'Escapa de la rutina y vive una aventura inolvidable durante varios días de conexión total con la naturaleza.\r\nDisfruta de noches mágicas bajo cielos estrellados en campamentos rodeados de paisajes andinos.\r\nCamina por impresionantes senderos entre montañas, valles y selva alta, descubriendo escenarios únicos.\r\nConquista el desafiante Paso Salkantay y admira vistas espectaculares del imponente nevado.\r\nAsciende a la hermosa Laguna y maravíllate con sus aguas turquesas.\r\nDescubre la diversidad de flora y fauna andina acompañado de un guía experto durante toda la experiencia.', 'Escape the routine and experience an unforgettable adventure over several days of complete connection with nature.\r\nEnjoy magical nights under starry skies at camps surrounded by Andean landscapes.\r\n Hike along stunning trails through mountains, valleys, and high jungle, discovering unique scenes.\r\n Conquer the challenging Salkantay Pass and admire spectacular views of the magnificent snow-capped peak.\r\n Ascend to the beautiful lagoon and be amazed by its turquoise waters.\r\nExplore the diversity of Andean flora and fauna with an expert guide throughout the entire experience.', NULL, 'Explora nevados imponentes, lagunas turquesas y paisajes únicos en una aventura inolvidable llena de naturaleza y cultura.', 'Explore towering snow-capped peaks, turquoise lagoons, and unique landscapes in an unforgettable adventure filled with nature and culture.', 'AUSANGATE', 'AUSANGATE', NULL, NULL, 'DÍA 01: CUSCO – AUSANGATE * Inicio de la aventura en la cordillera andina * Este día inicia con el recojo desde tu hotel en Cusco para dirigirnos hacia la zona de inicio del trekking en la cordillera del Nevado Ausangate. Durante el trayecto, disfrutarás de paisajes andinos, comunidades locales y vistas impresionantes. Luego, iniciarás la caminata hacia el primer campamento rodeado de naturaleza. * Transporte Turístico + Trekking | Campamento | Moderada | 10–12 km | 5-7 horas | 3,400 m | 4,200 m | 4,300 m | 4,200 m *\r\n\r\nDÍA 02: AUSANGATE – PASOS DE MONTAÑA * Caminata entre glaciares y lagunas altoandinas * Iniciarás el día atravesando impresionantes pasos de alta montaña, rodeado de nevados, glaciares y lagunas de colores intensos. Disfrutarás de vistas panorámicas del Ausangate en un recorrido exigente pero inolvidable. * Trekking | Campamento | Moderada – Alta | 12–14 km | 6-8 horas | 4,200 m | 4,800 m | 5,000 m | 4,500 m *\r\n\r\nDÍA 03: AUSANGATE – MONTAÑA DE COLORES * Encuentro con el paisaje más icónico del Perú * Muy temprano iniciarás el ascenso hacia la impresionante Montaña de Siete Colores, donde disfrutarás de vistas únicas. Luego continuarás la caminata por paisajes altoandinos hacia el siguiente campamento. * Trekking | Campamento | Moderada – Alta | 10–12 km | 5-7 horas | 4,500 m | 5,000 m | 5,200 m | 4,600 m *\r\n\r\nDÍA 04: AUSANGATE – VALLES Y LAGUNAS * Naturaleza pura entre montañas nevadas * Recorrerás extensos valles altoandinos y lagunas cristalinas rodeadas de nevados, en una jornada más relajada para disfrutar del entorno natural y la tranquilidad de la cordillera. * Trekking | Campamento | Moderada | 10–13 km | 5-7 horas | 4,600 m | 4,500 m | 4,800 m | 4,100 m *\r\n\r\nDÍA 05: AUSANGATE – CUSCO * Fin de la aventura y retorno * Caminata final corta y traslado de regreso hacia Cusco, disfrutando de los últimos paisajes andinos antes de finalizar esta experiencia inolvidable. * Trekking + Transporte Turístico | No aplica | Fácil | 6–8 km | 3-4 horas | 4,100 m | 3,400 m | 4,200 m | 3,400 m *', '**DAY 01: CUSCO – AUSANGATE * Start of the adventure in the Andean mountain range * This day begins with a pickup from your hotel in Cusco to head towards the starting point of the trek in the Ausangate mountain range. During the journey, you will enjoy Andean landscapes, local communities, and impressive views. Then, you will start the hike towards the first campsite surrounded by nature. * Tourist Transport + Trekking | Campsite | Moderate | 10–12 km | 5-7 hours | 3,400 m | 4,200 m | 4,300 m | 4,200 m * **\r\n\r\n**DAY 02: AUSANGATE – MOUNTAIN PASSES * Hiking between glaciers and high Andean lagoons * You will start the day crossing impressive high mountain passes, surrounded by snow-capped peaks, glaciers, and lagoons of intense colors. You will enjoy panoramic views of Ausangate on a demanding but unforgettable journey. * Trekking | Campsite | Moderate – High | 12–14 km | 6-8 hours | 4,200 m | 4,800 m | 5,000 m | 4,500 m * **\r\n\r\n**DAY 03: AUSANGATE – RAINBOW MOUNTAIN * Encounter with Peru\'s most iconic landscape * Very early, you will start the ascent towards the impressive Seven Colors Mountain (Rainbow Mountain), where you will enjoy unique views. Then, you will continue the hike through high Andean landscapes towards the next campsite. * Trekking | Campsite | Moderate – High | 10–12 km | 5-7 hours | 4,500 m | 5,000 m | 5,200 m | 4,600 m * **\r\n\r\n**DAY 04: AUSANGATE – VALLEYS AND LAGOONS * Pure nature among snow-capped mountains * You will explore extensive high Andean valleys and crystalline lagoons surrounded by glaciers, in a more relaxed day to enjoy the natural environment and the tranquility of the mountain range. * Trekking | Campsite | Moderate | 10–13 km | 5-7 hours | 4,600 m | 4,500 m | 4,800 m | 4,100 m * **\r\n\r\n**DAY 05: AUSANGATE – CUSCO * End of the adventure and return * Short final hike and transfer back to Cusco, enjoying the last Andean landscapes before finishing this unforgettable experience.', 'DÍA 01: CUSCO – AUSANGATE | Descripción Corta\r\nDÍA 02: AUSANGATE – PASOS DE MONTAÑA | Descripción Corta\r\nDÍA 03: AUSANGATE – MONTAÑA DE COLORES | Descripción Corta\r\nDÍA 04: AUSANGATE – VALLES Y LAGUNAS | Descripción Corta\r\nDÍA 05: AUSANGATE – CUSCO | Descripción Corta', 'DAY 01: CUSCO – AUSANGATE | Short Description\r\nDAY 02: AUSANGATE – MOUNTAIN PASSES | Short Description\r\nDAY 03: AUSANGATE – RAINBOW MOUNTAIN | Short Description\r\nDAY 04: AUSANGATE – VALLEYS AND LAGOONS | Short Description\r\nDAY 05: AUSANGATE – CUSCO | Short Description', NULL, NULL, 'Permisos y entradas * Entrada a la ruta Ausangate | Tan pronto como recibamos tu información completa y el depósito que asegura tu reserva, gestionaremos todos los accesos necesarios para la caminata en la zona de Ausangate (según disponibilidad y condiciones climáticas). # Acceso a comunidades andinas | Incluye el ingreso a las áreas locales y rutas autorizadas durante todo el trekking alrededor del Ausangate. *\r\nServicio de Calidad * Guía Profesional | Nuestros guías oficiales de turismo hablan inglés y español, y cuentan con formación profesional y certificación en trekking de alta montaña. # Equipo de apoyo (arrieros y caballos) | Contamos con personal local que se encarga del transporte del equipo de campamento y alimentación durante toda la ruta. # Alimentación Completa | Disfruta de desayunos, almuerzos y cenas nutritivos preparados por nuestro chef de trekking durante los 5 días. *\r\nTransporte * Recojo del Hotel | Te recogemos de tu hotel en Cusco en transporte turístico para el grupo hasta el punto de inicio de la caminata. # Transporte de retorno | Incluye el traslado desde el punto final del trekking de regreso a Cusco. # Movilidad completa del tour | Todos los traslados necesarios están incluidos durante la caminata de 5 días alrededor del Ausangate. *', 'Transporte * Hotel pick-up | We pick you up from your hotel in Cusco in tourist transport for the group to the starting point of the hike. # Return transport | Includes transfer from the trek\'s endpoint back to Cusco. # Full tour mobility | All necessary transfers are included during the 5-day trek around Ausangate. *', 'Bolsa de dormir | No incluye sleeping bag, puede alquilar uno con nosotros por US$20.\r\nBastones de trekking | Se recomienda el uso de bastones con puntas de goma para proteger el camino.\r\nSeguro de viaje | No incluye seguro médico ni de accidentes, le sugerimos contratar uno antes de viajar.\r\nPropinas | Las propinas para el equipo de porteadores, cocineros y guías son voluntarias.\r\nAlmuerzo final | El último almuerzo en Aguas Calientes después de visitar Machu Picchu corre por su cuenta.\r\n', 'Bolsa de dormir | Sleeping bag not included, you can rent one from us for US$20.\r\nBastones de trekking | Use of trekking poles with rubber tips is recommended to protect the trail.\r\nSeguro de viaje | Travel insurance not included, we suggest you purchase one before traveling.\r\nPropinas | Tips for the porters, cooks, and guides are voluntary.\r\nAlmuerzo final | The final lunch in Aguas Calientes after visiting Machu Picchu is on your own.', 'Alquiler de Bolsa de Dormir * Bolsa de dormir profesional de pluma, resistente hasta -10°C. Ideal para las noches frías en los campamentos de altura. * \r\nBastones de Trekking * Par de bastones profesionales con puntas de goma (obligatorio para no dañar el camino inca). Ayudan a reducir el impacto en las rodillas durante los descensos. * \r\nAlquiler de Colchoneta Inflable * Para mayor comodidad durante las noches de campamento, ofrecemos colchonetas inflables de la marca Therm-a-rest. *', 'Sleeping Bag Rental * Professional down sleeping bag, resistant to -10°C (14°F). Ideal for cold nights at high-altitude campsites. *\r\nTrekking Poles * Pair of professional trekking poles with rubber tips (mandatory to avoid damaging the Inca trail). Help reduce impact on knees during descents. * \r\nInflatable Sleeping Pad Rental * For greater comfort during camping nights, we offer Therm-a-rest brand inflatable sleeping pads. * ', '\"Tour privado de Camino Inca a Machu Picchu\" Puedes salir cualquier día de la semana, de marzo a enero. No realizamos esta caminata en febrero debido a la temporada de lluvias y al mantenimiento.\r\n\r\n# Precio del tour 2026\r\n\r\nPrecio grupal: \r\nPago por adelantado requerido: \r\nSaldo (Cusco):  (por lo general, se paga en Cusco después de la sesión informativa).\r\n\r\nEste viaje para grupos pequeños está garantizado para operar con solo dos invitados. Ten en cuenta que PayPal cobra una tarifa del 5%, monto que te pedimos que cubras ya que se debe al uso de tu servicio.\r\n\r\n# Extras y actualizaciones\r\n\r\nHay servicios complementarios y mejoras que se pueden incluir en este viaje.\r\n\r\n* Montaña Huayna Picchu:\r\n* Montaña Machu Picchu: \r\n* Montaña Huchuy Picchu: \r\n\r\n# Extensiones y ofertas\r\n\r\nHay varias extensiones que puedes incluir a tu gran aventura en Perú.\r\n\r\n* City Tour Cusco: \r\n* Valle Sagrado de los Incas: \r\n* Montaña de Colores Vinicunca: \r\n\r\n# Garantía de precio\r\n\r\nUna vez confirmada tu reserva, te garantizamos que el precio no aumentará, sean cuales sean las circunstancias. Por lo tanto, antes de reservar...', '\"Private Inca Trail to Machu Picchu Tour\" You can depart any day of the week, from March to January. We do not operate this trek in February due to the rainy season and maintenance.\r\n\r\n#2026 Tour Price\r\nGroup price: \r\nAdvance payment required:\r\nBalance (Cusco):  (usually paid in Cusco after the briefing).\r\n\r\nThis small group journey is guaranteed to operate with just two guests. Please note that PayPal charges a 5% fee, which we ask you to cover as it is due to the use of their service.\r\n\r\n#Extras and upgrades\r\nThere are complementary services and upgrades that can be included in this trip.\r\n\r\n*Huayna Picchu Mountain: \r\n*Machu Picchu Mountain: \r\n*Huchuy Picchu Mountain:\r\n\r\n#Extensions and offers\r\n\r\nThere are several extensions you can include in your great adventure in Peru.\r\n\r\n*Cusco City Tour: \r\n*Sacred Valley of the Incas: \r\n*Vinicunca Rainbow Mountain: \r\n\r\n#Price guarantee\r\n\r\nOnce your reservation is confirmed, we guarantee that the price will not increase, no matter the circumstances. Therefore, before booking...', 'INDISPENSABLE\r\nPasaporte vigente * premium_1775257158_0.jpeg\r\nDinero extra * 1775261528_preguntas_freguentes.jpeg\r\nMedicamentos personales * 1775261634_descarga_1.jpeg\r\nBotella de agua * 1775261661_images_2.jpeg\r\nBloqueador solar * 1775261674_images_1.jpeg\r\nRepelente de insectos * 1775261634_descarga_1.jpeg\r\nProductos de aseo * 1775261661_images_2.jpeg\r\n\r\nINDUMENTARIA\r\nBotas de montaña * premium_1775257158_0.jpeg\r\nCalzado ligero * 1775261528_preguntas_freguentes.jpeg\r\nPantalones para caminata * 1775261634_descarga_1.jpeg\r\nCalcetines de caminata * 1775261674_images_1.jpeg\r\nPolos de secado rápido * 1775261661_images_2.jpeg\r\nCasaca térmica * premium_1775257158_0.jpeg', 'ESSENTIALS\r\nValid passport * premium_1775257158_0.jpeg\r\nExtra cash * 1775261528_preguntas_freguentes.jpeg\r\nPersonal medications * 1775261634_descarga_1.jpeg\r\nWater bottle * 1775261661_images_2.jpeg\r\nSunscreen * 1775261674_images_1.jpeg\r\nInsect repellent * 1775261634_descarga_1.jpeg\r\nToiletries * 1775261661_images_2.jpeg\r\n\r\nCLOTHING/GEAR\r\nHiking boots * premium_1775257158_0.jpeg\r\nLight footwear * 1775261528_preguntas_freguentes.jpeg\r\nHiking pants * 1775261634_descarga_1.jpeg\r\nHiking socks * 1775261674_images_1.jpeg\r\nQuick-dry shirts * 1775261661_images_2.jpeg\r\nThermal jacket * premium_1775257158_0.jpeg', '995.00', '50', '0', '0.00', '0.00', '0.00', 'persona', '', '', '1775670848_tour.png', 'activo', '1', '2026-04-08 12:51:11', '0', 'USD', '0', '0', '2', '', '5,200 MSNM', 'Moderado', '', '', '6D,6A,6C', '6D,6A,6C', '1775755806_folleto.pdf', '1775672022_mapa.png', '1775671676_g1.jpg', '1775671676_g2.jpg', '1775671676_g3.jpg', NULL, 'El acceso a los principales destinos turísticos en Perú está regulado por entidades oficiales como el Ministerio de Cultura, quienes controlan la disponibilidad y el ingreso a sitios históricos.\r\n\r\nPara ingresar a ciertos atractivos, es obligatorio contar con una reserva o permiso previo que coincida con los datos personales del viajero (nombre completo, documento de identidad o pasaporte y nacionalidad).\r\n\r\nLas agencias de turismo autorizadas son las únicas que pueden gestionar estos permisos de forma legal y segura.\r\n\r\nLos ingresos tienen disponibilidad limitada, por lo que se recomienda realizar la reserva con anticipación.\r\n\r\nEn caso de querer modificar la fecha de tu viaje, estará sujeto a disponibilidad y puede requerir una nueva reserva.\r\n\r\nEstas son disposiciones oficiales que todos los visitantes deben respetar. Si no encuentras disponibilidad para la fecha deseada, existen alternativas igualmente increíbles que podemos recomendarte para que disfrutes al máximo tu experiencia en Perú.', 'Access to the main tourist destinations in Peru is regulated by official entities such as the Ministry of Culture, which control the availability and entry to historical sites.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Salud y Preparación Física * Aclimatación en Altitud | Es vital llegar a Cusco al menos 2 o 3 días antes para que su cuerpo se adapte gradualmente a los 3,400 metros de altura. # Alimentación Sugerida | Beba abundante mate de coca caliente, evite el alcohol y las comidas pesadas las primeras 24 horas. # Signos de Alerta | Si siente dolor de cabeza persistente o náuseas, descanse de inmediato y avise a nuestro personal de apoyo. * \r\nDocumentación y Seguros * Pasaporte y Visas | Debe portar su pasaporte físico original y vigente. No se aceptan copias ni fotos para los controles oficiales en la ruta. # Seguro de Viaje | Es obligatorio contar con un seguro que cubra rescate en montaña, evacuación aeromédica y gastos médicos de aventura para su tranquilidad. * \r\nDescarga de Guías Oficiales * Manual del Viajero | Haz clic en el botón de abajo para descargar la guía completa de preparación previa al viaje, consejos de salud y protocolos de seguridad de IntiPath Tours. * \r\nEquipo Técnico y Ropa * Sistema de Capas | El clima en los Andes cambia rápido; lleve casaca de plumas, cortavientos, polos de secado rápido y mallas térmicas. # Calzado Especializado | Use botas de trekking impermeables y con buen agarre (plantilla vibram sugerida) para evitar resbalones en terrenos húmedos o pedregosos. # Bastones de Trekking | Recomendamos el uso de bastones con puntas de goma para proteger el suelo del camino inca y mejorar su estabilidad. *\r\nPreguntas y Logística * Briefing Informativo | Una noche antes de la salida programada, nos reuniremos en su hotel a las 18:00 hrs para la charla final con su guía asignado. # Propinas y Extras | Las propinas para el equipo de porteadores y cocineros son voluntarias y se entregan al finalizar la expedición como muestra de agradecimiento. *\r\nItinerarios y Mapas * Mapa Detallado de Ruta | Descarga aquí el mapa técnico con altitudes, puntos de campamento, paradas de almuerzo y puntos de control día por día. # Respeto al Patrimonio | Practicamos turismo responsable; por favor, no deje basura en la ruta y respete los senderos señalizados por los guardaparques. *\r\nGuía Completa de Trekking * Todo lo que necesitas saber | Accede al documento final con la lista de chequeo (check-list) completa para que no olvides nada en tu maleta antes de partir a la aventura. *', 'Health and Physical Preparation * Altitude Acclimatization | It is vital to arrive in Cusco at least 2 or 3 days before so that your body gradually adapts to the 3,400 meters of altitude. # Suggested Diet | Drink plenty of hot coca tea, avoid alcohol and heavy meals for the first 24 hours. # Warning Signs | If you feel a persistent headache or nausea, rest immediately and notify our support staff. * Documentation and Insurance * Passport and Visas | You must carry your original and valid physical passport. Copies or photos are not accepted for official checkpoints along the route. # Travel Insurance | For your peace of mind, it is mandatory to have insurance that covers mountain rescue, aeromedical evacuation, and adventure medical expenses. * Download Official Guides * Traveler\'s Manual | Click the button below to download the complete pre-trip preparation guide, health tips, and safety protocols from IntiPath Tours. * Technical Equipment and Clothing * Layering System | The weather in the Andes changes fast; bring a down jacket, windbreaker, quick-dry shirts, and thermal leggings. # Specialized Footwear | Use waterproof trekking boots with good grip (Vibram sole suggested) to avoid slipping on wet or stony terrain. # Trekking Poles | We recommend using poles with rubber tips to protect the Inca Trail floor and improve your stability. * Questions and Logistics * Informational Briefing | One night before the scheduled departure, we will meet at your hotel at 18:00 hrs for the final talk with your assigned guide. # Tips and Extras | Tips for the porters and cooks team are voluntary and are given at the end of the expedition as a token of appreciation. * Itineraries and Maps * Detailed Route Map | Download the technical map here with altitudes, campsites, lunch stops, and checkpoints day by day. # Respect for Heritage | We practice responsible tourism; please do not leave trash on the route and respect the trails marked by the park rangers. * Complete Trekking Guide * Everything you need to know | Access the final document with the complete check-list so you don\'t forget anything in your suitcase before starting the adventure. *', '1776669159_69e5d1e7c3df0.jpeg', NULL, NULL);
INSERT INTO `tours` (`id`, `titulo`, `titulo_en`, `destacados`, `destacados_en`, `slug`, `descripcion_corta`, `descripcion_corta_en`, `titulo_corto`, `titulo_corto_en`, `descripcion_detallada`, `descripcion_detallada_en`, `itinerario`, `itinerario_en`, `itinerario_resumen`, `itinerario_resumen_en`, `info_importante`, `info_importante_en`, `incluye`, `incluye_en`, `no_incluye`, `no_incluye_en`, `extras_texto`, `extras_texto_en`, `aclimatacion_texto`, `aclimatacion_texto_en`, `lista_equipaje`, `lista_equipaje_en`, `precio`, `porcentaje_adelanto`, `max_personas`, `precio_grupal`, `pago_adelantado`, `saldo_cusco`, `tipo_precio`, `duracion`, `duracion_en`, `imagen_principal`, `estado`, `en_menu`, `fecha_creacion`, `mostrar_precio`, `moneda`, `es_recomendado`, `en_oferta`, `id_categoria`, `video_url`, `altitud_max`, `dificultad`, `ubicacion_texto`, `distancia_caminata`, `comidas_info`, `comidas_info_en`, `folleto_pdf`, `mapa_imagen`, `img_galeria1`, `img_galeria2`, `img_galeria3`, `img_galeria4`, `info_importante_detallada`, `info_importante_detallada_en`, `pq_titulo1`, `pq_desc1`, `pq_img1`, `pq_titulo2`, `pq_desc2`, `pq_img2`, `pq_titulo3`, `pq_desc3`, `pq_img3`, `antes_de_viajar`, `antes_de_viajar_en`, `galeria_itinerario`, `parent_id`, `precio_nino`) VALUES ('39', 'AUSANGATE & LAGUNA SIBINACOCHA  - 7 DIAS', '', 'Escapa de la rutina y sumérgete en la inmensidad de los Andes durante siete días inolvidables.\r\nExplora la majestuosa cordillera del Nevado Ausangate, rodeado de paisajes de alta montaña únicos.\r\nCamina entre lagunas cristalinas, glaciares y comunidades andinas llenas de tradición.\r\nConquista desafiantes pasos de gran altitud y admira vistas espectaculares en cada jornada.\r\nDescubre la impresionante Laguna Sibinacocha y maravíllate con su inmensidad y belleza natural.\r\nConecta con la naturaleza y descubre la riqueza de flora y fauna andina junto a nuestro guía experto.', '', NULL, 'Vive una aventura de 7 días recorriendo el Nevado Ausangate y la Laguna Sibinacocha, explorando paisajes de alta montaña, lagunas cristalinas y comunidades andinas. Una experiencia exigente y única que combina naturaleza, cultura y vistas espectaculares en los Andes.', '', 'AUSANGATE & LAGUNA SIBINACOCHA', '', NULL, NULL, 'DÍA 01: CUSCO – OCONGATE – PACCHANTA * Inicio de la aventura en los Andes * Este día inicia con el recojo desde tu hotel en Cusco para dirigirnos hacia Ocongate y luego a Pacchanta, punto de inicio del trekking en la cordillera del Nevado Ausangate. Durante el trayecto, disfrutarás de paisajes andinos y comunidades locales. * 1D 1A 1 C | Campamento | Moderada | 8–10 km | 5-6 horas | 3,400 m | 4,200 m | 4,300 m | 4,200 m *\r\n\r\nDÍA 02: PACCHANTA – ABRA JAMPA – AUSANGATE * Caminata entre pasos de alta montaña * Inicio de la caminata hacia el Abra Jampa, rodeado de montañas, glaciares y paisajes espectaculares, hasta llegar a la zona de Ausangate. * 1D 1A 1 C | Campamento | Moderada – Alta | 10–12 km | 6-7 horas | 4,200 m | 4,800 m | 5,000 m | 4,500 m *\r\n\r\nDÍA 03: AUSANGATE – LAGUNA WAYRAQMACHAY – YANAMAYO * Ruta de lagunas altoandinas * Caminata a través de paisajes impresionantes, pasando por la laguna Wayraqmachay y continuando hacia Yanamayo, rodeado de naturaleza pura. * 1D 1A 1 C | Campamento | Moderada – Alta | 12–14 km | 6-7 horas | 4,500 m | 4,700 m | 5,000 m | 4,600 m *\r\n\r\nDÍA 04: YANAMAYO – ABRA DEL CÓNDOR – LAGUNA SIBINACOCHA * Conexión con la inmensidad andina * Ascenso hacia el Abra del Cóndor y descenso hacia la impresionante Laguna Sibinacocha, una de las más grandes de la región. * 1D 1A 1 C | Campamento | Alta | 12–14 km | 7-8 horas | 4,600 m | 5,000 m | 5,200 m | 4,900 m *\r\n\r\nDÍA 05: LAGUNA SIBINACOCHA – LAGUNA CCASCCARA * Exploración de paisajes remotos * Caminata bordeando la laguna Sibinacocha y atravesando paisajes de alta montaña hasta llegar a la laguna Ccasccara. * 1D 1A 1 C | Campamento | Moderada – Alta | 10–12 km | 6-7 horas | 4,900 m | 4,700 m | 5,000 m | 4,600 m *\r\n\r\nDÍA 06: LAGUNA CCASCCARA – PHINIYA * Descenso hacia comunidades andinas * Descenso progresivo hacia Phiniya, disfrutando de paisajes altoandinos, fauna local y comunidades tradicionales. * 1D 1A 1 C | Campamento | Moderada | 10–12 km | 5-6 horas | 4,600 m | 4,300 m | 4,800 m | 4,200 m *\r\n\r\nDÍA 07: PHINIYA – SANTA BÁRBARA – CUSCO * Fin de la aventura y retorno * Caminata final hacia Santa Bárbara, donde abordaremos el transporte de regreso a Cusco, finalizando esta experiencia inolvidable. * 1D 1A 1 C | Turístico | No aplica | Fácil | 6–8 km | 3-4 horas | 4,200 m | 3,400 m | 4,200 m | 3,400 m *', '', 'DÍA 01: CUSCO – OCONGATE – PACCHANTA * Descripción Corta *\r\nDÍA 02: PACCHANTA – ABRA JAMPA – AUSANGATE * Descripción Corta *\r\nDÍA 03: AUSANGATE – LAGUNA WAYRAQMACHAY – YANAMAYO * Descripción Corta *\r\nDÍA 04: YANAMAYO – ABRA DEL CÓNDOR – LAGUNA SIBINACOCHA * Descripción Corta *\r\nDÍA 05: LAGUNA SIBINACOCHA – LAGUNA CCASCCARA * Descripción Corta *\r\nDÍA 06: LAGUNA CCASCCARA – PHINIYA * Descripción Corta *\r\nDÍA 07: PHINIYA – SANTA BÁRBARA – CUSCO * Descripción Corta *', '', NULL, NULL, 'Permisos y entradas * Entrada a Ausangate y Sibinacocha | Incluye el acceso a la cordillera del Nevado Ausangate y la impresionante Laguna Sibinacocha, áreas naturales de gran belleza en los Andes. *\r\nServicio de Calidad * Guía Profesional | Nuestros guías oficiales de turismo hablan inglés y español, y cuentan con formación profesional y certificación. # Equipo de Campamento | Contamos con personal especializado que se encargará del equipo de campamento y logística durante toda la ruta. # Alimentación Completa | Disfruta de desayunos, almuerzos y cenas nutritivos preparados por nuestro chef de trekking. *\r\nTransporte * Recojo del Hotel | Te recogemos de tu hotel en Cusco en transporte turístico para el grupo hasta el punto de inicio de la caminata. # Transporte Turístico | Incluye traslado de ida (Cusco – inicio del trekking) y retorno (final de ruta – Cusco). *', '', 'Bolsa de dormir | No incluye sleeping bag, puede alquilar uno con nosotros\r\nBastones de trekking | Se recomienda el uso de bastones con puntas de goma para proteger el camino.\r\nSeguro de viaje | No incluye seguro médico ni de accidentes, le sugerimos contratar uno antes de viajar.\r\nPropinas | Las propinas para el equipo de porteadores, cocineros y guías son voluntarias.', '', 'Alquiler de Bolsa de Dormir * Bolsa de dormir profesional de pluma, resistente hasta -10°C. Ideal para las noches frías en los campamentos de altura. * \r\nBastones de Trekking * Par de bastones profesionales con puntas de goma (obligatorio para no dañar el camino inca). Ayudan a reducir el impacto en las rodillas durante los descensos. * \r\nAlquiler de Colchoneta Inflable * Para mayor comodidad durante las noches de campamento, ofrecemos colchonetas inflables de la marca Therm-a-rest. * ', '', '\"Tour Ausangate y Sibinacocha 7 Días\" Puedes salir cualquier día de la semana durante todo el año. No recomendamos realizar este trekking en febrero debido a la temporada de lluvias y condiciones variables en la ruta.\r\n\r\n# Precio del tour 2026\r\n\r\nPrecio grupal: \r\nPago por adelantado requerido: \r\nSaldo (Cusco):(por lo general, se paga en Cusco después de la sesión informativa).\r\n\r\nEste viaje para grupos pequeños está garantizado para operar con solo dos invitados. Ten en cuenta que PayPal cobra una tarifa del 5%, monto que te pedimos que cubras ya que se debe al uso de tu servicio.\r\n\r\n# Extras y actualizaciones\r\n\r\nHay servicios complementarios y mejoras que se pueden incluir en este viaje.\r\n\r\n- Bolsa de dormir: \r\n- Bastones de trekking:\r\n- Caballo adicional para carga personal: \r\n\r\n# Extensiones y ofertas\r\n\r\nHay varias extensiones que puedes incluir a tu gran aventura en Perú.\r\n\r\n- City Tour Cusco: \r\n- Valle Sagrado de los Incas: \r\n- Montaña de Colores Vinicunca: \r\n\r\n# Garantía de precio\r\n\r\nUna vez confirmada tu reserva, te garantizamos que el precio no aumentará, sean cuales sean las circunstancias. Por lo tanto, antes de reservar...', '', 'INDISPENSABLE\r\nPasaporte vigente * 1776266661_69dfada59054b.jpg\r\nDinero extra * 1776266661_69dfada59063e.jpg\r\nMedicamentos personales * 1776266661_69dfada590746.jpg\r\nBotella de agua * 1776266661_69dfada59084a.jpg\r\nBloqueador solar * 1776266661_69dfada5908ed.jpg\r\nRepelente de insectos * 1776266661_69dfada5909e5.jpg\r\nProductos de aseo * 1776266661_69dfada590af0.jpg\r\n\r\nINDUMENTARIA\r\nBotas de montaña * 1776266661_69dfada590c31.jpg\r\nCalzado ligero * 1776266661_69dfada590bbf.jpg\r\nPantalones para caminata * 1776266661_69dfada590ce0.jpg\r\nCalcetines de caminata * 1776266661_69dfada590d7e.jpeg\r\nPolos de secado rápido * 1776266661_69dfada590e0f.jpg\r\nCasaca térmica * 1776266661_69dfada590e7d.jpg', '', '995.00', '50', '0', '0.00', '0.00', '0.00', 'persona', '7 DIAS', '', '1775757853_tour.jpg', 'activo', '0', '2026-04-09 12:35:40', '1', 'USD', '0', '0', '2', '', '5,200 MSNM', 'Desafiante', '', '', '3D 3A 3C AL DIA ', '', '1775767363_folleto.pdf', NULL, '1775766777_g1.jpg', '1775766777_g2.jpg', '1775766777_g3.jpg', NULL, 'El acceso a los principales destinos turísticos en Perú está regulado por entidades oficiales como el Ministerio de Cultura, quienes controlan la disponibilidad y el ingreso a sitios históricos.\r\n\r\n Para ingresar a ciertos atractivos, es obligatorio contar con una reserva o permiso previo que coincida con los datos personales del viajero (nombre completo, documento de identidad o pasaporte y nacionalidad).\r\n\r\n Las agencias de turismo autorizadas son las únicas que pueden gestionar estos permisos de forma legal y segura.\r\n\r\n Los ingresos tienen disponibilidad limitada, por lo que se recomienda realizar la reserva con anticipación.\r\n\r\n En caso de querer modificar la fecha de tu viaje, estará sujeto a disponibilidad y puede requerir una nueva reserva.\r\n\r\nEstas son disposiciones oficiales que todos los visitantes deben respetar. Si no encuentras disponibilidad para la fecha deseada, existen alternativas igualmente increíbles que podemos recomendarte para que disfrutes al máximo tu experiencia en Perú.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Salud y Preparación Física * Aclimatación en Altitud | Es vital llegar a Cusco al menos 2 o 3 días antes para que su cuerpo se adapte gradualmente a los 3,400 metros de altura. # Alimentación Sugerida | Beba abundante mate de coca caliente, evite el alcohol y las comidas pesadas las primeras 24 horas. # Signos de Alerta | Si siente dolor de cabeza persistente o náuseas, descanse de inmediato y avise a nuestro personal de apoyo. * 1776271151_69dfbf2f70566.jpg\r\nDocumentación y Seguros * Pasaporte y Visas | Debe portar su pasaporte físico original y vigente. No se aceptan copias ni fotos para los controles oficiales en la ruta. # Seguro de Viaje | Es obligatorio contar con un seguro que cubra rescate en montaña, evacuación aeromédica y gastos médicos de aventura para su tranquilidad. * 1776271151_69dfbf2f7081f.jpg\r\nDescarga de Guías Oficiales * Manual del Viajero | Haz clic en el botón de abajo para descargar la guía completa de preparación previa al viaje, consejos de salud y protocolos de seguridad de IntiPath Tours. * 1776271151_69dfbf2f706f4.jpg\r\nEquipo Técnico y Ropa * Sistema de Capas | El clima en los Andes cambia rápido; lleve casaca de plumas, cortavientos, polos de secado rápido y mallas térmicas. # Calzado Especializado | Use botas de trekking impermeables y con buen agarre (plantilla vibram sugerida) para evitar resbalones en terrenos húmedos o pedregosos. # Bastones de Trekking | Recomendamos el uso de bastones con puntas de goma para proteger el suelo del camino inca y mejorar su estabilidad. * 1776271151_69dfbf2f6cde1.jpg\r\nPreguntas y Logística * Briefing Informativo | Una noche antes de la salida programada, nos reuniremos en su hotel a las 18:00 hrs para la charla final con su guía asignado. # Propinas y Extras | Las propinas para el equipo de porteadores y cocineros son voluntarias y se entregan al finalizar la expedición como muestra de agradecimiento. * 1776271151_69dfbf2f709cf.png\r\nItinerarios y Mapas * Mapa Detallado de Ruta | Descarga aquí el mapa técnico con altitudes, puntos de campamento, paradas de almuerzo y puntos de control día por día. # Respeto al Patrimonio | Practicamos turismo responsable; por favor, no deje basura en la ruta y respete los senderos señalizados por los guardaparques. * 1776271151_69dfbf2f6cf85.jpg\r\nGuía Completa de Trekking * Todo lo que necesitas saber | Accede al documento final con la lista de chequeo (check-list) completa para que no olvides nada en tu maleta antes de partir a la aventura. * 1776271151_69dfbf2f70771.jpg', '', '', '33', NULL);
INSERT INTO `tours` (`id`, `titulo`, `titulo_en`, `destacados`, `destacados_en`, `slug`, `descripcion_corta`, `descripcion_corta_en`, `titulo_corto`, `titulo_corto_en`, `descripcion_detallada`, `descripcion_detallada_en`, `itinerario`, `itinerario_en`, `itinerario_resumen`, `itinerario_resumen_en`, `info_importante`, `info_importante_en`, `incluye`, `incluye_en`, `no_incluye`, `no_incluye_en`, `extras_texto`, `extras_texto_en`, `aclimatacion_texto`, `aclimatacion_texto_en`, `lista_equipaje`, `lista_equipaje_en`, `precio`, `porcentaje_adelanto`, `max_personas`, `precio_grupal`, `pago_adelantado`, `saldo_cusco`, `tipo_precio`, `duracion`, `duracion_en`, `imagen_principal`, `estado`, `en_menu`, `fecha_creacion`, `mostrar_precio`, `moneda`, `es_recomendado`, `en_oferta`, `id_categoria`, `video_url`, `altitud_max`, `dificultad`, `ubicacion_texto`, `distancia_caminata`, `comidas_info`, `comidas_info_en`, `folleto_pdf`, `mapa_imagen`, `img_galeria1`, `img_galeria2`, `img_galeria3`, `img_galeria4`, `info_importante_detallada`, `info_importante_detallada_en`, `pq_titulo1`, `pq_desc1`, `pq_img1`, `pq_titulo2`, `pq_desc2`, `pq_img2`, `pq_titulo3`, `pq_desc3`, `pq_img3`, `antes_de_viajar`, `antes_de_viajar_en`, `galeria_itinerario`, `parent_id`, `precio_nino`) VALUES ('44', 'FULL DAY TOURS', 'FULL DAY TOURS', '', '', NULL, 'Tours de un dia recorriendo cusco y sitios arqueológicos', '', 'TOURS DE UN DIA', 'DAY TOURS', NULL, NULL, '', '', '', '', NULL, NULL, '', '', '', '', '', '', '', '', '', '', '150.00', '50', '0', '0.00', '0.00', '0.00', 'persona', '1 día completo (Full Day)', '', '1776092869_principal.jpg', 'activo', '1', '2026-04-13 10:04:08', '0', 'USD', '0', '0', '3', '', '', 'Moderado', '', '', '', '', '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '', NULL, NULL);
