INSERT INTO `usuarios` (`id`, `usuario`, `nombres`, `apellidos`, `email`, `direccion`, `telefono`, `password`, `permisos`, `estado`, `fecha_creacion`, `reset_token`, `token_expira`) VALUES ('2', 'c.sanchez', 'CARLOS', 'SANCHEZ GUEVARA', 'guido.villamonte@gmail.com', 'AV. COSTANERA E-24', '937398157', '$2y$10$hCZWQjbC4FJ4bUCSKY8CfuRi5VEbkSuepRC7SXK14UJKGNEZ8t6QO', 'mensajes,sliders', '1', '2026-03-27 00:47:36', NULL, NULL);

