INSERT INTO `vacantes` (`id`, `titulo_es`, `titulo_en`, `ubicacion_es`, `ubicacion_en`, `estado`, `archivo_pdf`, `link_pdf`, `fecha_registro`, `banner_titulo`, `banner_titulo_en`, `banner_subtitulo`, `banner_subtitulo_en`, `intro_titulo`, `intro_titulo_en`, `intro_descripcion`, `intro_descripcion_en`, `valor1_tit`, `valor1_tit_en`, `valor1_desc`, `valor1_desc_en`, `valor2_tit`, `valor2_tit_en`, `valor2_desc`, `valor2_desc_en`, `valor3_tit`, `valor3_tit_en`, `valor3_desc`, `valor3_desc_en`, `cta_titulo`, `cta_titulo_en`, `cta_descripcion`, `cta_descripcion_en`, `cta_boton_txt`, `cta_boton_txt_en`) VALUES ('1', 'CONFIG_BASE', NULL, NULL, NULL, 'Abierto', NULL, NULL, '2026-05-14 03:03:01', 'Únete a nuestro equipo', 'Join our team', 'Construye el futuro del turismo con nosotros', 'Build the future of tourism with us', NULL, NULL, '# Sé parte de la familia IntiPath Tours\r\nNos apasiona crear experiencias inolvidables en los Andes de Perú. Buscamos personas dinámicas, comprometidas y listas para crecer profesionalmente en un ambiente laboral positivo, innovador y enfocado en el turismo sostenible.\r\n\r\n## Sostenibilidad\r\n[icon:seedling]\r\nCuidamos profundamente nuestras rutas de caminata, el ecosistema natural y trabajamos de la mano con el desarrollo de las comunidades nativas.\r\n\r\n## Trabajo en Equipo\r\n[icon:users]\r\nLa colaboración, la comunicación asertiva y el apoyo mutuo impulsan cada uno de los pasos que damos dentro y fuera de la oficina.\r\n\r\n## Desarrollo Profesional\r\n[icon:chart-line]\r\nPotenciamos las habilidades de todo nuestro personal administrativo y de campo para construir juntos una línea de carrera sólida a largo plazo.', '# Be part of the IntiPath Tours family\r\nWe are passionate about creating unforgettable experiences in the Peruvian Andes. We look for dynamic, committed individuals ready to grow professionally in a positive, innovative environment focused on sustainable tourism.\r\n\r\n## Sustainability\r\n[icon:seedling]\r\nWe deeply care about our trekking trails and the natural ecosystem, working hand in hand with the development of native communities.\r\n\r\n## Teamwork\r\n[icon:users]\r\nCollaboration, assertive communication, and mutual support drive every single step we take both inside and outside the office.\r\n\r\n## Professional Growth\r\n[icon:chart-line]\r\nWe empower all our office and field staff skills to build a strong, long-term professional career path together.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '', '', '', '');

